/* AKTİVA - Mal Kabul günlük bilgi kartı. Forklift/push sisteminden bağımsız. */
(()=>{'use strict';
const tips=[["Mal Kabul","İrsaliye kontrolü · Sabah ilk kabul","Vardiyanın ilk teslimatında: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Eksik belge","Teslimat evrakı eksik olduğunda: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Okuyucu arızası","Barkod okuyucu kullanılamadığında: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · İade dönüşü","Geri gelen ürünler ayrıştırılırken: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Manuel giriş","Barkod yerine elle kod yazılırken: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Eğitim uygulaması","Personel iş başında eğitim alırken: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Gün sonu raporu","Günün işlemleri raporlanırken: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Sayım günü","Depoda planlı sayım yapılırken: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Bayram öncesi","Sevkiyat hacmi artmışken: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Palet değişimi","Yük başka bir palete aktarılırken: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Kampanya dönemi","Ürün hareketi normalden hızlıyken: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Kalabalık saha","Yaya ve ekipman trafiği arttığında: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Hafta başı","Haftanın ilk sevkiyatında: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Alan doluluğu","Bekleme alanı dolmaya başladığında: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Dar koridor","Çalışma alanı daraldığında: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Vardiya devri","İş başka personele devredilirken: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Akşam vardiyası","Günün son kabul işleminde: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Erken teslimat","Araç randevudan erken geldiğinde: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Sabah ilk kabul","Vardiyanın ilk teslimatında: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Eksik belge","Teslimat evrakı eksik olduğunda: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Okuyucu arızası","Barkod okuyucu kullanılamadığında: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · İade dönüşü","Geri gelen ürünler ayrıştırılırken: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Manuel giriş","Barkod yerine elle kod yazılırken: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Eğitim uygulaması","Personel iş başında eğitim alırken: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Gün sonu raporu","Günün işlemleri raporlanırken: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Sayım günü","Depoda planlı sayım yapılırken: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Bayram öncesi","Sevkiyat hacmi artmışken: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Palet değişimi","Yük başka bir palete aktarılırken: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Kampanya dönemi","Ürün hareketi normalden hızlıyken: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Kalabalık saha","Yaya ve ekipman trafiği arttığında: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Hafta başı","Haftanın ilk sevkiyatında: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Alan doluluğu","Bekleme alanı dolmaya başladığında: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Dar koridor","Çalışma alanı daraldığında: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Vardiya devri","İş başka personele devredilirken: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Akşam vardiyası","Günün son kabul işleminde: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Erken teslimat","Araç randevudan erken geldiğinde: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Sabah ilk kabul","Vardiyanın ilk teslimatında: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Eksik belge","Teslimat evrakı eksik olduğunda: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Okuyucu arızası","Barkod okuyucu kullanılamadığında: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · İade dönüşü","Geri gelen ürünler ayrıştırılırken: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Manuel giriş","Barkod yerine elle kod yazılırken: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Eğitim uygulaması","Personel iş başında eğitim alırken: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Gün sonu raporu","Günün işlemleri raporlanırken: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Sayım günü","Depoda planlı sayım yapılırken: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Bayram öncesi","Sevkiyat hacmi artmışken: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Palet değişimi","Yük başka bir palete aktarılırken: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Kampanya dönemi","Ürün hareketi normalden hızlıyken: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Kalabalık saha","Yaya ve ekipman trafiği arttığında: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Hafta başı","Haftanın ilk sevkiyatında: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Alan doluluğu","Bekleme alanı dolmaya başladığında: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Dar koridor","Çalışma alanı daraldığında: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Vardiya devri","İş başka personele devredilirken: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Akşam vardiyası","Günün son kabul işleminde: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Erken teslimat","Araç randevudan erken geldiğinde: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Sabah ilk kabul","Vardiyanın ilk teslimatında: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Eksik belge","Teslimat evrakı eksik olduğunda: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Okuyucu arızası","Barkod okuyucu kullanılamadığında: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · İade dönüşü","Geri gelen ürünler ayrıştırılırken: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Manuel giriş","Barkod yerine elle kod yazılırken: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Eğitim uygulaması","Personel iş başında eğitim alırken: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Gün sonu raporu","Günün işlemleri raporlanırken: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Sayım günü","Depoda planlı sayım yapılırken: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Bayram öncesi","Sevkiyat hacmi artmışken: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Palet değişimi","Yük başka bir palete aktarılırken: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Kampanya dönemi","Ürün hareketi normalden hızlıyken: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Kalabalık saha","Yaya ve ekipman trafiği arttığında: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Hafta başı","Haftanın ilk sevkiyatında: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Alan doluluğu","Bekleme alanı dolmaya başladığında: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Dar koridor","Çalışma alanı daraldığında: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Vardiya devri","İş başka personele devredilirken: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Akşam vardiyası","Günün son kabul işleminde: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Erken teslimat","Araç randevudan erken geldiğinde: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Sabah ilk kabul","Vardiyanın ilk teslimatında: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Eksik belge","Teslimat evrakı eksik olduğunda: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Okuyucu arızası","Barkod okuyucu kullanılamadığında: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · İade dönüşü","Geri gelen ürünler ayrıştırılırken: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Manuel giriş","Barkod yerine elle kod yazılırken: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Eğitim uygulaması","Personel iş başında eğitim alırken: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Gün sonu raporu","Günün işlemleri raporlanırken: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Sayım günü","Depoda planlı sayım yapılırken: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Bayram öncesi","Sevkiyat hacmi artmışken: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Palet değişimi","Yük başka bir palete aktarılırken: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Kampanya dönemi","Ürün hareketi normalden hızlıyken: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Kalabalık saha","Yaya ve ekipman trafiği arttığında: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Hafta başı","Haftanın ilk sevkiyatında: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Alan doluluğu","Bekleme alanı dolmaya başladığında: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Dar koridor","Çalışma alanı daraldığında: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Vardiya devri","İş başka personele devredilirken: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Akşam vardiyası","Günün son kabul işleminde: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Erken teslimat","Araç randevudan erken geldiğinde: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Sabah ilk kabul","Vardiyanın ilk teslimatında: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Eksik belge","Teslimat evrakı eksik olduğunda: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Okuyucu arızası","Barkod okuyucu kullanılamadığında: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · İade dönüşü","Geri gelen ürünler ayrıştırılırken: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Manuel giriş","Barkod yerine elle kod yazılırken: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Eğitim uygulaması","Personel iş başında eğitim alırken: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Gün sonu raporu","Günün işlemleri raporlanırken: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Sayım günü","Depoda planlı sayım yapılırken: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Bayram öncesi","Sevkiyat hacmi artmışken: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Palet değişimi","Yük başka bir palete aktarılırken: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Kampanya dönemi","Ürün hareketi normalden hızlıyken: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Kalabalık saha","Yaya ve ekipman trafiği arttığında: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Hafta başı","Haftanın ilk sevkiyatında: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Alan doluluğu","Bekleme alanı dolmaya başladığında: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Dar koridor","Çalışma alanı daraldığında: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Vardiya devri","İş başka personele devredilirken: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Akşam vardiyası","Günün son kabul işleminde: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Erken teslimat","Araç randevudan erken geldiğinde: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Sabah ilk kabul","Vardiyanın ilk teslimatında: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Eksik belge","Teslimat evrakı eksik olduğunda: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Okuyucu arızası","Barkod okuyucu kullanılamadığında: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · İade dönüşü","Geri gelen ürünler ayrıştırılırken: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Manuel giriş","Barkod yerine elle kod yazılırken: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Eğitim uygulaması","Personel iş başında eğitim alırken: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Gün sonu raporu","Günün işlemleri raporlanırken: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Sayım günü","Depoda planlı sayım yapılırken: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Bayram öncesi","Sevkiyat hacmi artmışken: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Palet değişimi","Yük başka bir palete aktarılırken: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Kampanya dönemi","Ürün hareketi normalden hızlıyken: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Kalabalık saha","Yaya ve ekipman trafiği arttığında: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Hafta başı","Haftanın ilk sevkiyatında: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Alan doluluğu","Bekleme alanı dolmaya başladığında: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Dar koridor","Çalışma alanı daraldığında: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Vardiya devri","İş başka personele devredilirken: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Akşam vardiyası","Günün son kabul işleminde: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Erken teslimat","Araç randevudan erken geldiğinde: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Sabah ilk kabul","Vardiyanın ilk teslimatında: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Eksik belge","Teslimat evrakı eksik olduğunda: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Okuyucu arızası","Barkod okuyucu kullanılamadığında: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · İade dönüşü","Geri gelen ürünler ayrıştırılırken: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Manuel giriş","Barkod yerine elle kod yazılırken: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Eğitim uygulaması","Personel iş başında eğitim alırken: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Gün sonu raporu","Günün işlemleri raporlanırken: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Sayım günü","Depoda planlı sayım yapılırken: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Bayram öncesi","Sevkiyat hacmi artmışken: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Palet değişimi","Yük başka bir palete aktarılırken: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Kampanya dönemi","Ürün hareketi normalden hızlıyken: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Kalabalık saha","Yaya ve ekipman trafiği arttığında: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Hafta başı","Haftanın ilk sevkiyatında: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Alan doluluğu","Bekleme alanı dolmaya başladığında: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Dar koridor","Çalışma alanı daraldığında: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Vardiya devri","İş başka personele devredilirken: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Akşam vardiyası","Günün son kabul işleminde: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Erken teslimat","Araç randevudan erken geldiğinde: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Sabah ilk kabul","Vardiyanın ilk teslimatında: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Eksik belge","Teslimat evrakı eksik olduğunda: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Okuyucu arızası","Barkod okuyucu kullanılamadığında: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · İade dönüşü","Geri gelen ürünler ayrıştırılırken: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Manuel giriş","Barkod yerine elle kod yazılırken: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Eğitim uygulaması","Personel iş başında eğitim alırken: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Gün sonu raporu","Günün işlemleri raporlanırken: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Sayım günü","Depoda planlı sayım yapılırken: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Bayram öncesi","Sevkiyat hacmi artmışken: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Palet değişimi","Yük başka bir palete aktarılırken: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Kampanya dönemi","Ürün hareketi normalden hızlıyken: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Kalabalık saha","Yaya ve ekipman trafiği arttığında: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Hafta başı","Haftanın ilk sevkiyatında: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Alan doluluğu","Bekleme alanı dolmaya başladığında: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Dar koridor","Çalışma alanı daraldığında: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Vardiya devri","İş başka personele devredilirken: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Akşam vardiyası","Günün son kabul işleminde: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Erken teslimat","Araç randevudan erken geldiğinde: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Sabah ilk kabul","Vardiyanın ilk teslimatında: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Eksik belge","Teslimat evrakı eksik olduğunda: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Okuyucu arızası","Barkod okuyucu kullanılamadığında: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · İade dönüşü","Geri gelen ürünler ayrıştırılırken: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Manuel giriş","Barkod yerine elle kod yazılırken: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Eğitim uygulaması","Personel iş başında eğitim alırken: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Gün sonu raporu","Günün işlemleri raporlanırken: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Sayım günü","Depoda planlı sayım yapılırken: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Bayram öncesi","Sevkiyat hacmi artmışken: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Palet değişimi","Yük başka bir palete aktarılırken: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Kampanya dönemi","Ürün hareketi normalden hızlıyken: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Kalabalık saha","Yaya ve ekipman trafiği arttığında: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Hafta başı","Haftanın ilk sevkiyatında: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Alan doluluğu","Bekleme alanı dolmaya başladığında: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Dar koridor","Çalışma alanı daraldığında: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Vardiya devri","İş başka personele devredilirken: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Akşam vardiyası","Günün son kabul işleminde: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Erken teslimat","Araç randevudan erken geldiğinde: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Sabah ilk kabul","Vardiyanın ilk teslimatında: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Eksik belge","Teslimat evrakı eksik olduğunda: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Okuyucu arızası","Barkod okuyucu kullanılamadığında: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · İade dönüşü","Geri gelen ürünler ayrıştırılırken: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Manuel giriş","Barkod yerine elle kod yazılırken: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Eğitim uygulaması","Personel iş başında eğitim alırken: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Gün sonu raporu","Günün işlemleri raporlanırken: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Sayım günü","Depoda planlı sayım yapılırken: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Bayram öncesi","Sevkiyat hacmi artmışken: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Palet değişimi","Yük başka bir palete aktarılırken: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Kampanya dönemi","Ürün hareketi normalden hızlıyken: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Kalabalık saha","Yaya ve ekipman trafiği arttığında: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Hafta başı","Haftanın ilk sevkiyatında: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Alan doluluğu","Bekleme alanı dolmaya başladığında: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Dar koridor","Çalışma alanı daraldığında: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Vardiya devri","İş başka personele devredilirken: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Akşam vardiyası","Günün son kabul işleminde: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Erken teslimat","Araç randevudan erken geldiğinde: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Sabah ilk kabul","Vardiyanın ilk teslimatında: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Eksik belge","Teslimat evrakı eksik olduğunda: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Okuyucu arızası","Barkod okuyucu kullanılamadığında: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · İade dönüşü","Geri gelen ürünler ayrıştırılırken: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Manuel giriş","Barkod yerine elle kod yazılırken: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Eğitim uygulaması","Personel iş başında eğitim alırken: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Gün sonu raporu","Günün işlemleri raporlanırken: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Sayım günü","Depoda planlı sayım yapılırken: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Bayram öncesi","Sevkiyat hacmi artmışken: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Palet değişimi","Yük başka bir palete aktarılırken: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Kampanya dönemi","Ürün hareketi normalden hızlıyken: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Kalabalık saha","Yaya ve ekipman trafiği arttığında: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Hafta başı","Haftanın ilk sevkiyatında: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Alan doluluğu","Bekleme alanı dolmaya başladığında: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Dar koridor","Çalışma alanı daraldığında: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Vardiya devri","İş başka personele devredilirken: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Akşam vardiyası","Günün son kabul işleminde: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Erken teslimat","Araç randevudan erken geldiğinde: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Sabah ilk kabul","Vardiyanın ilk teslimatında: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Eksik belge","Teslimat evrakı eksik olduğunda: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Okuyucu arızası","Barkod okuyucu kullanılamadığında: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · İade dönüşü","Geri gelen ürünler ayrıştırılırken: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Manuel giriş","Barkod yerine elle kod yazılırken: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Eğitim uygulaması","Personel iş başında eğitim alırken: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Gün sonu raporu","Günün işlemleri raporlanırken: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Sayım günü","Depoda planlı sayım yapılırken: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Bayram öncesi","Sevkiyat hacmi artmışken: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Palet değişimi","Yük başka bir palete aktarılırken: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Kampanya dönemi","Ürün hareketi normalden hızlıyken: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Kalabalık saha","Yaya ve ekipman trafiği arttığında: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Hafta başı","Haftanın ilk sevkiyatında: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Alan doluluğu","Bekleme alanı dolmaya başladığında: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Dar koridor","Çalışma alanı daraldığında: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Vardiya devri","İş başka personele devredilirken: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Akşam vardiyası","Günün son kabul işleminde: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Erken teslimat","Araç randevudan erken geldiğinde: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Sabah ilk kabul","Vardiyanın ilk teslimatında: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Eksik belge","Teslimat evrakı eksik olduğunda: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Okuyucu arızası","Barkod okuyucu kullanılamadığında: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · İade dönüşü","Geri gelen ürünler ayrıştırılırken: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Manuel giriş","Barkod yerine elle kod yazılırken: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Eğitim uygulaması","Personel iş başında eğitim alırken: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Gün sonu raporu","Günün işlemleri raporlanırken: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Sayım günü","Depoda planlı sayım yapılırken: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Bayram öncesi","Sevkiyat hacmi artmışken: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Palet değişimi","Yük başka bir palete aktarılırken: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Kampanya dönemi","Ürün hareketi normalden hızlıyken: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Kalabalık saha","Yaya ve ekipman trafiği arttığında: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Hafta başı","Haftanın ilk sevkiyatında: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Alan doluluğu","Bekleme alanı dolmaya başladığında: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Dar koridor","Çalışma alanı daraldığında: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Vardiya devri","İş başka personele devredilirken: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Akşam vardiyası","Günün son kabul işleminde: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Erken teslimat","Araç randevudan erken geldiğinde: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Sabah ilk kabul","Vardiyanın ilk teslimatında: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Eksik belge","Teslimat evrakı eksik olduğunda: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Okuyucu arızası","Barkod okuyucu kullanılamadığında: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · İade dönüşü","Geri gelen ürünler ayrıştırılırken: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Manuel giriş","Barkod yerine elle kod yazılırken: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Eğitim uygulaması","Personel iş başında eğitim alırken: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Gün sonu raporu","Günün işlemleri raporlanırken: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Sayım günü","Depoda planlı sayım yapılırken: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Bayram öncesi","Sevkiyat hacmi artmışken: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Palet değişimi","Yük başka bir palete aktarılırken: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Kampanya dönemi","Ürün hareketi normalden hızlıyken: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Kalabalık saha","Yaya ve ekipman trafiği arttığında: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Hafta başı","Haftanın ilk sevkiyatında: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Alan doluluğu","Bekleme alanı dolmaya başladığında: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Dar koridor","Çalışma alanı daraldığında: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Vardiya devri","İş başka personele devredilirken: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Akşam vardiyası","Günün son kabul işleminde: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Erken teslimat","Araç randevudan erken geldiğinde: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Sabah ilk kabul","Vardiyanın ilk teslimatında: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Eksik belge","Teslimat evrakı eksik olduğunda: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Okuyucu arızası","Barkod okuyucu kullanılamadığında: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · İade dönüşü","Geri gelen ürünler ayrıştırılırken: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Manuel giriş","Barkod yerine elle kod yazılırken: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Eğitim uygulaması","Personel iş başında eğitim alırken: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Gün sonu raporu","Günün işlemleri raporlanırken: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Sayım günü","Depoda planlı sayım yapılırken: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Bayram öncesi","Sevkiyat hacmi artmışken: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Palet değişimi","Yük başka bir palete aktarılırken: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Kampanya dönemi","Ürün hareketi normalden hızlıyken: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Kalabalık saha","Yaya ve ekipman trafiği arttığında: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Hafta başı","Haftanın ilk sevkiyatında: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Alan doluluğu","Bekleme alanı dolmaya başladığında: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Dar koridor","Çalışma alanı daraldığında: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Vardiya devri","İş başka personele devredilirken: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Akşam vardiyası","Günün son kabul işleminde: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Erken teslimat","Araç randevudan erken geldiğinde: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Sabah ilk kabul","Vardiyanın ilk teslimatında: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Eksik belge","Teslimat evrakı eksik olduğunda: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Okuyucu arızası","Barkod okuyucu kullanılamadığında: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · İade dönüşü","Geri gelen ürünler ayrıştırılırken: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Manuel giriş","Barkod yerine elle kod yazılırken: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Eğitim uygulaması","Personel iş başında eğitim alırken: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Gün sonu raporu","Günün işlemleri raporlanırken: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Sayım günü","Depoda planlı sayım yapılırken: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Bayram öncesi","Sevkiyat hacmi artmışken: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Palet değişimi","Yük başka bir palete aktarılırken: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Kampanya dönemi","Ürün hareketi normalden hızlıyken: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Kalabalık saha","Yaya ve ekipman trafiği arttığında: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Hafta başı","Haftanın ilk sevkiyatında: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Alan doluluğu","Bekleme alanı dolmaya başladığında: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Dar koridor","Çalışma alanı daraldığında: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Vardiya devri","İş başka personele devredilirken: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Akşam vardiyası","Günün son kabul işleminde: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Erken teslimat","Araç randevudan erken geldiğinde: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Sabah ilk kabul","Vardiyanın ilk teslimatında: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Eksik belge","Teslimat evrakı eksik olduğunda: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Okuyucu arızası","Barkod okuyucu kullanılamadığında: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · İade dönüşü","Geri gelen ürünler ayrıştırılırken: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Manuel giriş","Barkod yerine elle kod yazılırken: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Eğitim uygulaması","Personel iş başında eğitim alırken: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Gün sonu raporu","Günün işlemleri raporlanırken: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Sayım günü","Depoda planlı sayım yapılırken: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Bayram öncesi","Sevkiyat hacmi artmışken: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Palet değişimi","Yük başka bir palete aktarılırken: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Kampanya dönemi","Ürün hareketi normalden hızlıyken: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Kalabalık saha","Yaya ve ekipman trafiği arttığında: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Hafta başı","Haftanın ilk sevkiyatında: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Alan doluluğu","Bekleme alanı dolmaya başladığında: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Dar koridor","Çalışma alanı daraldığında: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Vardiya devri","İş başka personele devredilirken: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Akşam vardiyası","Günün son kabul işleminde: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Erken teslimat","Araç randevudan erken geldiğinde: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Sabah ilk kabul","Vardiyanın ilk teslimatında: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Eksik belge","Teslimat evrakı eksik olduğunda: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Okuyucu arızası","Barkod okuyucu kullanılamadığında: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · İade dönüşü","Geri gelen ürünler ayrıştırılırken: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Manuel giriş","Barkod yerine elle kod yazılırken: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Eğitim uygulaması","Personel iş başında eğitim alırken: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Gün sonu raporu","Günün işlemleri raporlanırken: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Sayım günü","Depoda planlı sayım yapılırken: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Bayram öncesi","Sevkiyat hacmi artmışken: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Palet değişimi","Yük başka bir palete aktarılırken: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Kampanya dönemi","Ürün hareketi normalden hızlıyken: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Kalabalık saha","Yaya ve ekipman trafiği arttığında: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Hafta başı","Haftanın ilk sevkiyatında: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Alan doluluğu","Bekleme alanı dolmaya başladığında: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Dar koridor","Çalışma alanı daraldığında: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Vardiya devri","İş başka personele devredilirken: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Akşam vardiyası","Günün son kabul işleminde: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Erken teslimat","Araç randevudan erken geldiğinde: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Sabah ilk kabul","Vardiyanın ilk teslimatında: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Eksik belge","Teslimat evrakı eksik olduğunda: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Okuyucu arızası","Barkod okuyucu kullanılamadığında: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · İade dönüşü","Geri gelen ürünler ayrıştırılırken: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Manuel giriş","Barkod yerine elle kod yazılırken: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Eğitim uygulaması","Personel iş başında eğitim alırken: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Gün sonu raporu","Günün işlemleri raporlanırken: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Sayım günü","Depoda planlı sayım yapılırken: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Bayram öncesi","Sevkiyat hacmi artmışken: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Palet değişimi","Yük başka bir palete aktarılırken: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Kampanya dönemi","Ürün hareketi normalden hızlıyken: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Kalabalık saha","Yaya ve ekipman trafiği arttığında: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Hafta başı","Haftanın ilk sevkiyatında: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Alan doluluğu","Bekleme alanı dolmaya başladığında: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Dar koridor","Çalışma alanı daraldığında: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Vardiya devri","İş başka personele devredilirken: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Akşam vardiyası","Günün son kabul işleminde: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Erken teslimat","Araç randevudan erken geldiğinde: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Sabah ilk kabul","Vardiyanın ilk teslimatında: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Eksik belge","Teslimat evrakı eksik olduğunda: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Okuyucu arızası","Barkod okuyucu kullanılamadığında: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · İade dönüşü","Geri gelen ürünler ayrıştırılırken: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Manuel giriş","Barkod yerine elle kod yazılırken: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Eğitim uygulaması","Personel iş başında eğitim alırken: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Gün sonu raporu","Günün işlemleri raporlanırken: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Sayım günü","Depoda planlı sayım yapılırken: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Bayram öncesi","Sevkiyat hacmi artmışken: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Palet değişimi","Yük başka bir palete aktarılırken: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Kampanya dönemi","Ürün hareketi normalden hızlıyken: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Kalabalık saha","Yaya ve ekipman trafiği arttığında: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Hafta başı","Haftanın ilk sevkiyatında: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Alan doluluğu","Bekleme alanı dolmaya başladığında: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Dar koridor","Çalışma alanı daraldığında: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Vardiya devri","İş başka personele devredilirken: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Akşam vardiyası","Günün son kabul işleminde: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Erken teslimat","Araç randevudan erken geldiğinde: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Sabah ilk kabul","Vardiyanın ilk teslimatında: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Eksik belge","Teslimat evrakı eksik olduğunda: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Okuyucu arızası","Barkod okuyucu kullanılamadığında: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · İade dönüşü","Geri gelen ürünler ayrıştırılırken: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Manuel giriş","Barkod yerine elle kod yazılırken: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Eğitim uygulaması","Personel iş başında eğitim alırken: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Gün sonu raporu","Günün işlemleri raporlanırken: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Sayım günü","Depoda planlı sayım yapılırken: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Bayram öncesi","Sevkiyat hacmi artmışken: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Palet değişimi","Yük başka bir palete aktarılırken: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Kampanya dönemi","Ürün hareketi normalden hızlıyken: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Kalabalık saha","Yaya ve ekipman trafiği arttığında: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Hafta başı","Haftanın ilk sevkiyatında: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Alan doluluğu","Bekleme alanı dolmaya başladığında: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Dar koridor","Çalışma alanı daraldığında: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Vardiya devri","İş başka personele devredilirken: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Akşam vardiyası","Günün son kabul işleminde: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Erken teslimat","Araç randevudan erken geldiğinde: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Sabah ilk kabul","Vardiyanın ilk teslimatında: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Eksik belge","Teslimat evrakı eksik olduğunda: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Okuyucu arızası","Barkod okuyucu kullanılamadığında: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · İade dönüşü","Geri gelen ürünler ayrıştırılırken: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Manuel giriş","Barkod yerine elle kod yazılırken: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Eğitim uygulaması","Personel iş başında eğitim alırken: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Gün sonu raporu","Günün işlemleri raporlanırken: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Sayım günü","Depoda planlı sayım yapılırken: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Bayram öncesi","Sevkiyat hacmi artmışken: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Palet değişimi","Yük başka bir palete aktarılırken: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Kampanya dönemi","Ürün hareketi normalden hızlıyken: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Kalabalık saha","Yaya ve ekipman trafiği arttığında: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Hafta başı","Haftanın ilk sevkiyatında: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Alan doluluğu","Bekleme alanı dolmaya başladığında: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Dar koridor","Çalışma alanı daraldığında: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Vardiya devri","İş başka personele devredilirken: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Akşam vardiyası","Günün son kabul işleminde: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Erken teslimat","Araç randevudan erken geldiğinde: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Sabah ilk kabul","Vardiyanın ilk teslimatında: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Eksik belge","Teslimat evrakı eksik olduğunda: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Okuyucu arızası","Barkod okuyucu kullanılamadığında: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · İade dönüşü","Geri gelen ürünler ayrıştırılırken: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Manuel giriş","Barkod yerine elle kod yazılırken: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Eğitim uygulaması","Personel iş başında eğitim alırken: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Gün sonu raporu","Günün işlemleri raporlanırken: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Sayım günü","Depoda planlı sayım yapılırken: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Bayram öncesi","Sevkiyat hacmi artmışken: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Palet değişimi","Yük başka bir palete aktarılırken: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Kampanya dönemi","Ürün hareketi normalden hızlıyken: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Kalabalık saha","Yaya ve ekipman trafiği arttığında: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Hafta başı","Haftanın ilk sevkiyatında: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Alan doluluğu","Bekleme alanı dolmaya başladığında: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Dar koridor","Çalışma alanı daraldığında: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Vardiya devri","İş başka personele devredilirken: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Akşam vardiyası","Günün son kabul işleminde: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Erken teslimat","Araç randevudan erken geldiğinde: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Sabah ilk kabul","Vardiyanın ilk teslimatında: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Eksik belge","Teslimat evrakı eksik olduğunda: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Okuyucu arızası","Barkod okuyucu kullanılamadığında: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · İade dönüşü","Geri gelen ürünler ayrıştırılırken: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Manuel giriş","Barkod yerine elle kod yazılırken: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Eğitim uygulaması","Personel iş başında eğitim alırken: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Gün sonu raporu","Günün işlemleri raporlanırken: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Sayım günü","Depoda planlı sayım yapılırken: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Bayram öncesi","Sevkiyat hacmi artmışken: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Palet değişimi","Yük başka bir palete aktarılırken: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Kampanya dönemi","Ürün hareketi normalden hızlıyken: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Kalabalık saha","Yaya ve ekipman trafiği arttığında: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Hafta başı","Haftanın ilk sevkiyatında: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Alan doluluğu","Bekleme alanı dolmaya başladığında: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Dar koridor","Çalışma alanı daraldığında: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Vardiya devri","İş başka personele devredilirken: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Akşam vardiyası","Günün son kabul işleminde: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Erken teslimat","Araç randevudan erken geldiğinde: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Sabah ilk kabul","Vardiyanın ilk teslimatında: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Eksik belge","Teslimat evrakı eksik olduğunda: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Okuyucu arızası","Barkod okuyucu kullanılamadığında: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · İade dönüşü","Geri gelen ürünler ayrıştırılırken: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Manuel giriş","Barkod yerine elle kod yazılırken: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Eğitim uygulaması","Personel iş başında eğitim alırken: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Gün sonu raporu","Günün işlemleri raporlanırken: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Sayım günü","Depoda planlı sayım yapılırken: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Bayram öncesi","Sevkiyat hacmi artmışken: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Palet değişimi","Yük başka bir palete aktarılırken: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Kampanya dönemi","Ürün hareketi normalden hızlıyken: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Kalabalık saha","Yaya ve ekipman trafiği arttığında: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Hafta başı","Haftanın ilk sevkiyatında: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Alan doluluğu","Bekleme alanı dolmaya başladığında: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Dar koridor","Çalışma alanı daraldığında: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Vardiya devri","İş başka personele devredilirken: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Akşam vardiyası","Günün son kabul işleminde: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Erken teslimat","Araç randevudan erken geldiğinde: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Sabah ilk kabul","Vardiyanın ilk teslimatında: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Eksik belge","Teslimat evrakı eksik olduğunda: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Okuyucu arızası","Barkod okuyucu kullanılamadığında: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · İade dönüşü","Geri gelen ürünler ayrıştırılırken: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Manuel giriş","Barkod yerine elle kod yazılırken: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Eğitim uygulaması","Personel iş başında eğitim alırken: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Gün sonu raporu","Günün işlemleri raporlanırken: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Sayım günü","Depoda planlı sayım yapılırken: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Bayram öncesi","Sevkiyat hacmi artmışken: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Palet değişimi","Yük başka bir palete aktarılırken: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Kampanya dönemi","Ürün hareketi normalden hızlıyken: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Kalabalık saha","Yaya ve ekipman trafiği arttığında: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Hafta başı","Haftanın ilk sevkiyatında: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Alan doluluğu","Bekleme alanı dolmaya başladığında: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Dar koridor","Çalışma alanı daraldığında: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Vardiya devri","İş başka personele devredilirken: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Akşam vardiyası","Günün son kabul işleminde: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Erken teslimat","Araç randevudan erken geldiğinde: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Sabah ilk kabul","Vardiyanın ilk teslimatında: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Eksik belge","Teslimat evrakı eksik olduğunda: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Okuyucu arızası","Barkod okuyucu kullanılamadığında: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · İade dönüşü","Geri gelen ürünler ayrıştırılırken: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Manuel giriş","Barkod yerine elle kod yazılırken: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Eğitim uygulaması","Personel iş başında eğitim alırken: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Gün sonu raporu","Günün işlemleri raporlanırken: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Sayım günü","Depoda planlı sayım yapılırken: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Bayram öncesi","Sevkiyat hacmi artmışken: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Palet değişimi","Yük başka bir palete aktarılırken: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Kampanya dönemi","Ürün hareketi normalden hızlıyken: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Kalabalık saha","Yaya ve ekipman trafiği arttığında: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Hafta başı","Haftanın ilk sevkiyatında: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Alan doluluğu","Bekleme alanı dolmaya başladığında: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Dar koridor","Çalışma alanı daraldığında: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Vardiya devri","İş başka personele devredilirken: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Akşam vardiyası","Günün son kabul işleminde: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Erken teslimat","Araç randevudan erken geldiğinde: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Sabah ilk kabul","Vardiyanın ilk teslimatında: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Eksik belge","Teslimat evrakı eksik olduğunda: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Okuyucu arızası","Barkod okuyucu kullanılamadığında: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · İade dönüşü","Geri gelen ürünler ayrıştırılırken: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Manuel giriş","Barkod yerine elle kod yazılırken: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Eğitim uygulaması","Personel iş başında eğitim alırken: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Gün sonu raporu","Günün işlemleri raporlanırken: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Sayım günü","Depoda planlı sayım yapılırken: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Bayram öncesi","Sevkiyat hacmi artmışken: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Palet değişimi","Yük başka bir palete aktarılırken: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Kampanya dönemi","Ürün hareketi normalden hızlıyken: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Kalabalık saha","Yaya ve ekipman trafiği arttığında: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Hafta başı","Haftanın ilk sevkiyatında: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Alan doluluğu","Bekleme alanı dolmaya başladığında: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Dar koridor","Çalışma alanı daraldığında: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Vardiya devri","İş başka personele devredilirken: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Akşam vardiyası","Günün son kabul işleminde: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Erken teslimat","Araç randevudan erken geldiğinde: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Sabah ilk kabul","Vardiyanın ilk teslimatında: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Eksik belge","Teslimat evrakı eksik olduğunda: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Okuyucu arızası","Barkod okuyucu kullanılamadığında: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · İade dönüşü","Geri gelen ürünler ayrıştırılırken: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Manuel giriş","Barkod yerine elle kod yazılırken: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Eğitim uygulaması","Personel iş başında eğitim alırken: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Gün sonu raporu","Günün işlemleri raporlanırken: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Sayım günü","Depoda planlı sayım yapılırken: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Bayram öncesi","Sevkiyat hacmi artmışken: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Palet değişimi","Yük başka bir palete aktarılırken: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Kampanya dönemi","Ürün hareketi normalden hızlıyken: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Kalabalık saha","Yaya ve ekipman trafiği arttığında: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Hafta başı","Haftanın ilk sevkiyatında: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Alan doluluğu","Bekleme alanı dolmaya başladığında: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Dar koridor","Çalışma alanı daraldığında: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Vardiya devri","İş başka personele devredilirken: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Akşam vardiyası","Günün son kabul işleminde: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Erken teslimat","Araç randevudan erken geldiğinde: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Sabah ilk kabul","Vardiyanın ilk teslimatında: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Eksik belge","Teslimat evrakı eksik olduğunda: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Okuyucu arızası","Barkod okuyucu kullanılamadığında: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · İade dönüşü","Geri gelen ürünler ayrıştırılırken: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Manuel giriş","Barkod yerine elle kod yazılırken: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Eğitim uygulaması","Personel iş başında eğitim alırken: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Gün sonu raporu","Günün işlemleri raporlanırken: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Sayım günü","Depoda planlı sayım yapılırken: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Bayram öncesi","Sevkiyat hacmi artmışken: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Palet değişimi","Yük başka bir palete aktarılırken: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Kampanya dönemi","Ürün hareketi normalden hızlıyken: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Kalabalık saha","Yaya ve ekipman trafiği arttığında: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Hafta başı","Haftanın ilk sevkiyatında: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Alan doluluğu","Bekleme alanı dolmaya başladığında: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Dar koridor","Çalışma alanı daraldığında: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Vardiya devri","İş başka personele devredilirken: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Akşam vardiyası","Günün son kabul işleminde: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Erken teslimat","Araç randevudan erken geldiğinde: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Sabah ilk kabul","Vardiyanın ilk teslimatında: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Eksik belge","Teslimat evrakı eksik olduğunda: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Okuyucu arızası","Barkod okuyucu kullanılamadığında: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · İade dönüşü","Geri gelen ürünler ayrıştırılırken: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Manuel giriş","Barkod yerine elle kod yazılırken: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Eğitim uygulaması","Personel iş başında eğitim alırken: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Gün sonu raporu","Günün işlemleri raporlanırken: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Sayım günü","Depoda planlı sayım yapılırken: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Bayram öncesi","Sevkiyat hacmi artmışken: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Palet değişimi","Yük başka bir palete aktarılırken: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Kampanya dönemi","Ürün hareketi normalden hızlıyken: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Kalabalık saha","Yaya ve ekipman trafiği arttığında: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Hafta başı","Haftanın ilk sevkiyatında: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Alan doluluğu","Bekleme alanı dolmaya başladığında: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Dar koridor","Çalışma alanı daraldığında: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Vardiya devri","İş başka personele devredilirken: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Akşam vardiyası","Günün son kabul işleminde: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Erken teslimat","Araç randevudan erken geldiğinde: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Sabah ilk kabul","Vardiyanın ilk teslimatında: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Eksik belge","Teslimat evrakı eksik olduğunda: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Okuyucu arızası","Barkod okuyucu kullanılamadığında: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · İade dönüşü","Geri gelen ürünler ayrıştırılırken: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Manuel giriş","Barkod yerine elle kod yazılırken: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Eğitim uygulaması","Personel iş başında eğitim alırken: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Gün sonu raporu","Günün işlemleri raporlanırken: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Sayım günü","Depoda planlı sayım yapılırken: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Bayram öncesi","Sevkiyat hacmi artmışken: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Palet değişimi","Yük başka bir palete aktarılırken: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Kampanya dönemi","Ürün hareketi normalden hızlıyken: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Kalabalık saha","Yaya ve ekipman trafiği arttığında: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Hafta başı","Haftanın ilk sevkiyatında: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Alan doluluğu","Bekleme alanı dolmaya başladığında: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Dar koridor","Çalışma alanı daraldığında: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Vardiya devri","İş başka personele devredilirken: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Akşam vardiyası","Günün son kabul işleminde: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Erken teslimat","Araç randevudan erken geldiğinde: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Sabah ilk kabul","Vardiyanın ilk teslimatında: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Eksik belge","Teslimat evrakı eksik olduğunda: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Okuyucu arızası","Barkod okuyucu kullanılamadığında: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · İade dönüşü","Geri gelen ürünler ayrıştırılırken: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Manuel giriş","Barkod yerine elle kod yazılırken: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Eğitim uygulaması","Personel iş başında eğitim alırken: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Gün sonu raporu","Günün işlemleri raporlanırken: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Sayım günü","Depoda planlı sayım yapılırken: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Bayram öncesi","Sevkiyat hacmi artmışken: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Palet değişimi","Yük başka bir palete aktarılırken: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Kampanya dönemi","Ürün hareketi normalden hızlıyken: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Kalabalık saha","Yaya ve ekipman trafiği arttığında: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Hafta başı","Haftanın ilk sevkiyatında: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Alan doluluğu","Bekleme alanı dolmaya başladığında: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Dar koridor","Çalışma alanı daraldığında: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Vardiya devri","İş başka personele devredilirken: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Akşam vardiyası","Günün son kabul işleminde: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Erken teslimat","Araç randevudan erken geldiğinde: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Sabah ilk kabul","Vardiyanın ilk teslimatında: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Eksik belge","Teslimat evrakı eksik olduğunda: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Okuyucu arızası","Barkod okuyucu kullanılamadığında: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · İade dönüşü","Geri gelen ürünler ayrıştırılırken: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Manuel giriş","Barkod yerine elle kod yazılırken: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Eğitim uygulaması","Personel iş başında eğitim alırken: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Gün sonu raporu","Günün işlemleri raporlanırken: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Sayım günü","Depoda planlı sayım yapılırken: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Bayram öncesi","Sevkiyat hacmi artmışken: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Palet değişimi","Yük başka bir palete aktarılırken: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Kampanya dönemi","Ürün hareketi normalden hızlıyken: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Kalabalık saha","Yaya ve ekipman trafiği arttığında: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Hafta başı","Haftanın ilk sevkiyatında: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Alan doluluğu","Bekleme alanı dolmaya başladığında: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Dar koridor","Çalışma alanı daraldığında: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Vardiya devri","İş başka personele devredilirken: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Akşam vardiyası","Günün son kabul işleminde: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Erken teslimat","Araç randevudan erken geldiğinde: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Sabah ilk kabul","Vardiyanın ilk teslimatında: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Eksik belge","Teslimat evrakı eksik olduğunda: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Okuyucu arızası","Barkod okuyucu kullanılamadığında: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · İade dönüşü","Geri gelen ürünler ayrıştırılırken: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Manuel giriş","Barkod yerine elle kod yazılırken: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Eğitim uygulaması","Personel iş başında eğitim alırken: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Gün sonu raporu","Günün işlemleri raporlanırken: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Sayım günü","Depoda planlı sayım yapılırken: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Bayram öncesi","Sevkiyat hacmi artmışken: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Palet değişimi","Yük başka bir palete aktarılırken: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Kampanya dönemi","Ürün hareketi normalden hızlıyken: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Kalabalık saha","Yaya ve ekipman trafiği arttığında: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Hafta başı","Haftanın ilk sevkiyatında: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Alan doluluğu","Bekleme alanı dolmaya başladığında: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Dar koridor","Çalışma alanı daraldığında: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Vardiya devri","İş başka personele devredilirken: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Akşam vardiyası","Günün son kabul işleminde: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Erken teslimat","Araç randevudan erken geldiğinde: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Sabah ilk kabul","Vardiyanın ilk teslimatında: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Eksik belge","Teslimat evrakı eksik olduğunda: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Okuyucu arızası","Barkod okuyucu kullanılamadığında: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · İade dönüşü","Geri gelen ürünler ayrıştırılırken: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Manuel giriş","Barkod yerine elle kod yazılırken: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Eğitim uygulaması","Personel iş başında eğitim alırken: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Gün sonu raporu","Günün işlemleri raporlanırken: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Sayım günü","Depoda planlı sayım yapılırken: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Bayram öncesi","Sevkiyat hacmi artmışken: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Palet değişimi","Yük başka bir palete aktarılırken: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Kampanya dönemi","Ürün hareketi normalden hızlıyken: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Kalabalık saha","Yaya ve ekipman trafiği arttığında: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Hafta başı","Haftanın ilk sevkiyatında: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Alan doluluğu","Bekleme alanı dolmaya başladığında: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Dar koridor","Çalışma alanı daraldığında: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Vardiya devri","İş başka personele devredilirken: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Akşam vardiyası","Günün son kabul işleminde: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Erken teslimat","Araç randevudan erken geldiğinde: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Sabah ilk kabul","Vardiyanın ilk teslimatında: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Eksik belge","Teslimat evrakı eksik olduğunda: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Okuyucu arızası","Barkod okuyucu kullanılamadığında: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · İade dönüşü","Geri gelen ürünler ayrıştırılırken: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Manuel giriş","Barkod yerine elle kod yazılırken: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Eğitim uygulaması","Personel iş başında eğitim alırken: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Gün sonu raporu","Günün işlemleri raporlanırken: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Sayım günü","Depoda planlı sayım yapılırken: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Bayram öncesi","Sevkiyat hacmi artmışken: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Palet değişimi","Yük başka bir palete aktarılırken: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Kampanya dönemi","Ürün hareketi normalden hızlıyken: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Kalabalık saha","Yaya ve ekipman trafiği arttığında: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Hafta başı","Haftanın ilk sevkiyatında: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Alan doluluğu","Bekleme alanı dolmaya başladığında: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Dar koridor","Çalışma alanı daraldığında: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Vardiya devri","İş başka personele devredilirken: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Akşam vardiyası","Günün son kabul işleminde: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Erken teslimat","Araç randevudan erken geldiğinde: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Sabah ilk kabul","Vardiyanın ilk teslimatında: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Eksik belge","Teslimat evrakı eksik olduğunda: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Okuyucu arızası","Barkod okuyucu kullanılamadığında: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · İade dönüşü","Geri gelen ürünler ayrıştırılırken: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Manuel giriş","Barkod yerine elle kod yazılırken: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Eğitim uygulaması","Personel iş başında eğitim alırken: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Gün sonu raporu","Günün işlemleri raporlanırken: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Sayım günü","Depoda planlı sayım yapılırken: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Bayram öncesi","Sevkiyat hacmi artmışken: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Palet değişimi","Yük başka bir palete aktarılırken: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Kampanya dönemi","Ürün hareketi normalden hızlıyken: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Kalabalık saha","Yaya ve ekipman trafiği arttığında: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Hafta başı","Haftanın ilk sevkiyatında: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Alan doluluğu","Bekleme alanı dolmaya başladığında: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Dar koridor","Çalışma alanı daraldığında: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Vardiya devri","İş başka personele devredilirken: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Akşam vardiyası","Günün son kabul işleminde: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Erken teslimat","Araç randevudan erken geldiğinde: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Sabah ilk kabul","Vardiyanın ilk teslimatında: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Eksik belge","Teslimat evrakı eksik olduğunda: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Okuyucu arızası","Barkod okuyucu kullanılamadığında: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · İade dönüşü","Geri gelen ürünler ayrıştırılırken: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Manuel giriş","Barkod yerine elle kod yazılırken: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Eğitim uygulaması","Personel iş başında eğitim alırken: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Gün sonu raporu","Günün işlemleri raporlanırken: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Sayım günü","Depoda planlı sayım yapılırken: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Bayram öncesi","Sevkiyat hacmi artmışken: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Palet değişimi","Yük başka bir palete aktarılırken: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Kampanya dönemi","Ürün hareketi normalden hızlıyken: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Kalabalık saha","Yaya ve ekipman trafiği arttığında: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Hafta başı","Haftanın ilk sevkiyatında: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Alan doluluğu","Bekleme alanı dolmaya başladığında: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Dar koridor","Çalışma alanı daraldığında: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Vardiya devri","İş başka personele devredilirken: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Akşam vardiyası","Günün son kabul işleminde: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Erken teslimat","Araç randevudan erken geldiğinde: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Sabah ilk kabul","Vardiyanın ilk teslimatında: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Eksik belge","Teslimat evrakı eksik olduğunda: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Okuyucu arızası","Barkod okuyucu kullanılamadığında: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · İade dönüşü","Geri gelen ürünler ayrıştırılırken: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Manuel giriş","Barkod yerine elle kod yazılırken: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Eğitim uygulaması","Personel iş başında eğitim alırken: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Gün sonu raporu","Günün işlemleri raporlanırken: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Sayım günü","Depoda planlı sayım yapılırken: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Bayram öncesi","Sevkiyat hacmi artmışken: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Palet değişimi","Yük başka bir palete aktarılırken: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Kampanya dönemi","Ürün hareketi normalden hızlıyken: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Kalabalık saha","Yaya ve ekipman trafiği arttığında: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Hafta başı","Haftanın ilk sevkiyatında: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Alan doluluğu","Bekleme alanı dolmaya başladığında: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Dar koridor","Çalışma alanı daraldığında: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Vardiya devri","İş başka personele devredilirken: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Akşam vardiyası","Günün son kabul işleminde: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Erken teslimat","Araç randevudan erken geldiğinde: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Sabah ilk kabul","Vardiyanın ilk teslimatında: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Eksik belge","Teslimat evrakı eksik olduğunda: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Okuyucu arızası","Barkod okuyucu kullanılamadığında: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · İade dönüşü","Geri gelen ürünler ayrıştırılırken: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Manuel giriş","Barkod yerine elle kod yazılırken: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Eğitim uygulaması","Personel iş başında eğitim alırken: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Gün sonu raporu","Günün işlemleri raporlanırken: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Sayım günü","Depoda planlı sayım yapılırken: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Bayram öncesi","Sevkiyat hacmi artmışken: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Palet değişimi","Yük başka bir palete aktarılırken: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Kampanya dönemi","Ürün hareketi normalden hızlıyken: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Kalabalık saha","Yaya ve ekipman trafiği arttığında: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Hafta başı","Haftanın ilk sevkiyatında: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Alan doluluğu","Bekleme alanı dolmaya başladığında: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Dar koridor","Çalışma alanı daraldığında: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Vardiya devri","İş başka personele devredilirken: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Akşam vardiyası","Günün son kabul işleminde: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Erken teslimat","Araç randevudan erken geldiğinde: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Sabah ilk kabul","Vardiyanın ilk teslimatında: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Eksik belge","Teslimat evrakı eksik olduğunda: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Okuyucu arızası","Barkod okuyucu kullanılamadığında: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · İade dönüşü","Geri gelen ürünler ayrıştırılırken: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Manuel giriş","Barkod yerine elle kod yazılırken: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Eğitim uygulaması","Personel iş başında eğitim alırken: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Gün sonu raporu","Günün işlemleri raporlanırken: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Sayım günü","Depoda planlı sayım yapılırken: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Bayram öncesi","Sevkiyat hacmi artmışken: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Palet değişimi","Yük başka bir palete aktarılırken: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Kampanya dönemi","Ürün hareketi normalden hızlıyken: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Kalabalık saha","Yaya ve ekipman trafiği arttığında: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Hafta başı","Haftanın ilk sevkiyatında: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Alan doluluğu","Bekleme alanı dolmaya başladığında: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Dar koridor","Çalışma alanı daraldığında: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Vardiya devri","İş başka personele devredilirken: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Akşam vardiyası","Günün son kabul işleminde: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Erken teslimat","Araç randevudan erken geldiğinde: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Sabah ilk kabul","Vardiyanın ilk teslimatında: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Eksik belge","Teslimat evrakı eksik olduğunda: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Okuyucu arızası","Barkod okuyucu kullanılamadığında: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · İade dönüşü","Geri gelen ürünler ayrıştırılırken: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Manuel giriş","Barkod yerine elle kod yazılırken: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Eğitim uygulaması","Personel iş başında eğitim alırken: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Gün sonu raporu","Günün işlemleri raporlanırken: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Sayım günü","Depoda planlı sayım yapılırken: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Bayram öncesi","Sevkiyat hacmi artmışken: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Palet değişimi","Yük başka bir palete aktarılırken: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Kampanya dönemi","Ürün hareketi normalden hızlıyken: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Kalabalık saha","Yaya ve ekipman trafiği arttığında: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Hafta başı","Haftanın ilk sevkiyatında: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Alan doluluğu","Bekleme alanı dolmaya başladığında: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Dar koridor","Çalışma alanı daraldığında: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Vardiya devri","İş başka personele devredilirken: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Akşam vardiyası","Günün son kabul işleminde: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Erken teslimat","Araç randevudan erken geldiğinde: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Sabah ilk kabul","Vardiyanın ilk teslimatında: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Eksik belge","Teslimat evrakı eksik olduğunda: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Okuyucu arızası","Barkod okuyucu kullanılamadığında: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · İade dönüşü","Geri gelen ürünler ayrıştırılırken: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Manuel giriş","Barkod yerine elle kod yazılırken: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Eğitim uygulaması","Personel iş başında eğitim alırken: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Gün sonu raporu","Günün işlemleri raporlanırken: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Sayım günü","Depoda planlı sayım yapılırken: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Bayram öncesi","Sevkiyat hacmi artmışken: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Palet değişimi","Yük başka bir palete aktarılırken: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Kampanya dönemi","Ürün hareketi normalden hızlıyken: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Kalabalık saha","Yaya ve ekipman trafiği arttığında: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Hafta başı","Haftanın ilk sevkiyatında: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Alan doluluğu","Bekleme alanı dolmaya başladığında: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Dar koridor","Çalışma alanı daraldığında: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Vardiya devri","İş başka personele devredilirken: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Akşam vardiyası","Günün son kabul işleminde: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Erken teslimat","Araç randevudan erken geldiğinde: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Sabah ilk kabul","Vardiyanın ilk teslimatında: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Eksik belge","Teslimat evrakı eksik olduğunda: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Okuyucu arızası","Barkod okuyucu kullanılamadığında: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · İade dönüşü","Geri gelen ürünler ayrıştırılırken: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Manuel giriş","Barkod yerine elle kod yazılırken: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Eğitim uygulaması","Personel iş başında eğitim alırken: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Gün sonu raporu","Günün işlemleri raporlanırken: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Sayım günü","Depoda planlı sayım yapılırken: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Bayram öncesi","Sevkiyat hacmi artmışken: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Palet değişimi","Yük başka bir palete aktarılırken: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Kampanya dönemi","Ürün hareketi normalden hızlıyken: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Kalabalık saha","Yaya ve ekipman trafiği arttığında: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Hafta başı","Haftanın ilk sevkiyatında: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Alan doluluğu","Bekleme alanı dolmaya başladığında: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Dar koridor","Çalışma alanı daraldığında: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Vardiya devri","İş başka personele devredilirken: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Akşam vardiyası","Günün son kabul işleminde: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Erken teslimat","Araç randevudan erken geldiğinde: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Sabah ilk kabul","Vardiyanın ilk teslimatında: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Eksik belge","Teslimat evrakı eksik olduğunda: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Okuyucu arızası","Barkod okuyucu kullanılamadığında: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · İade dönüşü","Geri gelen ürünler ayrıştırılırken: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Manuel giriş","Barkod yerine elle kod yazılırken: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Eğitim uygulaması","Personel iş başında eğitim alırken: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Gün sonu raporu","Günün işlemleri raporlanırken: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Sayım günü","Depoda planlı sayım yapılırken: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Bayram öncesi","Sevkiyat hacmi artmışken: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Palet değişimi","Yük başka bir palete aktarılırken: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Kampanya dönemi","Ürün hareketi normalden hızlıyken: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Kalabalık saha","Yaya ve ekipman trafiği arttığında: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Hafta başı","Haftanın ilk sevkiyatında: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Alan doluluğu","Bekleme alanı dolmaya başladığında: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Dar koridor","Çalışma alanı daraldığında: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Vardiya devri","İş başka personele devredilirken: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Akşam vardiyası","Günün son kabul işleminde: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Erken teslimat","Araç randevudan erken geldiğinde: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Sabah ilk kabul","Vardiyanın ilk teslimatında: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Eksik belge","Teslimat evrakı eksik olduğunda: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Okuyucu arızası","Barkod okuyucu kullanılamadığında: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · İade dönüşü","Geri gelen ürünler ayrıştırılırken: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Manuel giriş","Barkod yerine elle kod yazılırken: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Eğitim uygulaması","Personel iş başında eğitim alırken: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Gün sonu raporu","Günün işlemleri raporlanırken: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Sayım günü","Depoda planlı sayım yapılırken: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Bayram öncesi","Sevkiyat hacmi artmışken: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Palet değişimi","Yük başka bir palete aktarılırken: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Kampanya dönemi","Ürün hareketi normalden hızlıyken: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Kalabalık saha","Yaya ve ekipman trafiği arttığında: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Hafta başı","Haftanın ilk sevkiyatında: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Alan doluluğu","Bekleme alanı dolmaya başladığında: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Dar koridor","Çalışma alanı daraldığında: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Vardiya devri","İş başka personele devredilirken: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Akşam vardiyası","Günün son kabul işleminde: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Erken teslimat","Araç randevudan erken geldiğinde: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Sabah ilk kabul","Vardiyanın ilk teslimatında: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Eksik belge","Teslimat evrakı eksik olduğunda: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Okuyucu arızası","Barkod okuyucu kullanılamadığında: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · İade dönüşü","Geri gelen ürünler ayrıştırılırken: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Manuel giriş","Barkod yerine elle kod yazılırken: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Eğitim uygulaması","Personel iş başında eğitim alırken: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Gün sonu raporu","Günün işlemleri raporlanırken: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Sayım günü","Depoda planlı sayım yapılırken: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Bayram öncesi","Sevkiyat hacmi artmışken: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Palet değişimi","Yük başka bir palete aktarılırken: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Kampanya dönemi","Ürün hareketi normalden hızlıyken: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Kalabalık saha","Yaya ve ekipman trafiği arttığında: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Hafta başı","Haftanın ilk sevkiyatında: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Alan doluluğu","Bekleme alanı dolmaya başladığında: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Dar koridor","Çalışma alanı daraldığında: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Vardiya devri","İş başka personele devredilirken: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Akşam vardiyası","Günün son kabul işleminde: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Erken teslimat","Araç randevudan erken geldiğinde: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Sabah ilk kabul","Vardiyanın ilk teslimatında: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Eksik belge","Teslimat evrakı eksik olduğunda: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Okuyucu arızası","Barkod okuyucu kullanılamadığında: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · İade dönüşü","Geri gelen ürünler ayrıştırılırken: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Manuel giriş","Barkod yerine elle kod yazılırken: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Eğitim uygulaması","Personel iş başında eğitim alırken: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Gün sonu raporu","Günün işlemleri raporlanırken: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Sayım günü","Depoda planlı sayım yapılırken: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Bayram öncesi","Sevkiyat hacmi artmışken: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Palet değişimi","Yük başka bir palete aktarılırken: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Kampanya dönemi","Ürün hareketi normalden hızlıyken: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Kalabalık saha","Yaya ve ekipman trafiği arttığında: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Hafta başı","Haftanın ilk sevkiyatında: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Alan doluluğu","Bekleme alanı dolmaya başladığında: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Dar koridor","Çalışma alanı daraldığında: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Vardiya devri","İş başka personele devredilirken: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Akşam vardiyası","Günün son kabul işleminde: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Erken teslimat","Araç randevudan erken geldiğinde: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Sabah ilk kabul","Vardiyanın ilk teslimatında: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Eksik belge","Teslimat evrakı eksik olduğunda: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Okuyucu arızası","Barkod okuyucu kullanılamadığında: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · İade dönüşü","Geri gelen ürünler ayrıştırılırken: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Manuel giriş","Barkod yerine elle kod yazılırken: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Eğitim uygulaması","Personel iş başında eğitim alırken: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Gün sonu raporu","Günün işlemleri raporlanırken: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Sayım günü","Depoda planlı sayım yapılırken: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Bayram öncesi","Sevkiyat hacmi artmışken: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Palet değişimi","Yük başka bir palete aktarılırken: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Kampanya dönemi","Ürün hareketi normalden hızlıyken: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Kalabalık saha","Yaya ve ekipman trafiği arttığında: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Hafta başı","Haftanın ilk sevkiyatında: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Alan doluluğu","Bekleme alanı dolmaya başladığında: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Dar koridor","Çalışma alanı daraldığında: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Vardiya devri","İş başka personele devredilirken: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Akşam vardiyası","Günün son kabul işleminde: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Erken teslimat","Araç randevudan erken geldiğinde: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Sabah ilk kabul","Vardiyanın ilk teslimatında: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Eksik belge","Teslimat evrakı eksik olduğunda: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Okuyucu arızası","Barkod okuyucu kullanılamadığında: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · İade dönüşü","Geri gelen ürünler ayrıştırılırken: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Manuel giriş","Barkod yerine elle kod yazılırken: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Eğitim uygulaması","Personel iş başında eğitim alırken: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Gün sonu raporu","Günün işlemleri raporlanırken: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Sayım günü","Depoda planlı sayım yapılırken: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Bayram öncesi","Sevkiyat hacmi artmışken: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Palet değişimi","Yük başka bir palete aktarılırken: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Kampanya dönemi","Ürün hareketi normalden hızlıyken: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Kalabalık saha","Yaya ve ekipman trafiği arttığında: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Hafta başı","Haftanın ilk sevkiyatında: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Alan doluluğu","Bekleme alanı dolmaya başladığında: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Dar koridor","Çalışma alanı daraldığında: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Vardiya devri","İş başka personele devredilirken: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Akşam vardiyası","Günün son kabul işleminde: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Erken teslimat","Araç randevudan erken geldiğinde: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Sabah ilk kabul","Vardiyanın ilk teslimatında: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Eksik belge","Teslimat evrakı eksik olduğunda: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Okuyucu arızası","Barkod okuyucu kullanılamadığında: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · İade dönüşü","Geri gelen ürünler ayrıştırılırken: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Manuel giriş","Barkod yerine elle kod yazılırken: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Eğitim uygulaması","Personel iş başında eğitim alırken: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Gün sonu raporu","Günün işlemleri raporlanırken: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Sayım günü","Depoda planlı sayım yapılırken: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Bayram öncesi","Sevkiyat hacmi artmışken: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Palet değişimi","Yük başka bir palete aktarılırken: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Kampanya dönemi","Ürün hareketi normalden hızlıyken: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Kalabalık saha","Yaya ve ekipman trafiği arttığında: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Hafta başı","Haftanın ilk sevkiyatında: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Alan doluluğu","Bekleme alanı dolmaya başladığında: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Dar koridor","Çalışma alanı daraldığında: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Vardiya devri","İş başka personele devredilirken: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Akşam vardiyası","Günün son kabul işleminde: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Erken teslimat","Araç randevudan erken geldiğinde: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Sabah ilk kabul","Vardiyanın ilk teslimatında: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Eksik belge","Teslimat evrakı eksik olduğunda: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Okuyucu arızası","Barkod okuyucu kullanılamadığında: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · İade dönüşü","Geri gelen ürünler ayrıştırılırken: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Manuel giriş","Barkod yerine elle kod yazılırken: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Eğitim uygulaması","Personel iş başında eğitim alırken: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Gün sonu raporu","Günün işlemleri raporlanırken: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Sayım günü","Depoda planlı sayım yapılırken: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Bayram öncesi","Sevkiyat hacmi artmışken: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Palet değişimi","Yük başka bir palete aktarılırken: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Kampanya dönemi","Ürün hareketi normalden hızlıyken: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Kalabalık saha","Yaya ve ekipman trafiği arttığında: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Hafta başı","Haftanın ilk sevkiyatında: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Alan doluluğu","Bekleme alanı dolmaya başladığında: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Dar koridor","Çalışma alanı daraldığında: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Vardiya devri","İş başka personele devredilirken: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Akşam vardiyası","Günün son kabul işleminde: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Erken teslimat","Araç randevudan erken geldiğinde: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Sabah ilk kabul","Vardiyanın ilk teslimatında: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Eksik belge","Teslimat evrakı eksik olduğunda: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Okuyucu arızası","Barkod okuyucu kullanılamadığında: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · İade dönüşü","Geri gelen ürünler ayrıştırılırken: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Manuel giriş","Barkod yerine elle kod yazılırken: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Eğitim uygulaması","Personel iş başında eğitim alırken: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Gün sonu raporu","Günün işlemleri raporlanırken: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Sayım günü","Depoda planlı sayım yapılırken: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Bayram öncesi","Sevkiyat hacmi artmışken: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Palet değişimi","Yük başka bir palete aktarılırken: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Kampanya dönemi","Ürün hareketi normalden hızlıyken: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Kalabalık saha","Yaya ve ekipman trafiği arttığında: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Hafta başı","Haftanın ilk sevkiyatında: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Alan doluluğu","Bekleme alanı dolmaya başladığında: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Dar koridor","Çalışma alanı daraldığında: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Vardiya devri","İş başka personele devredilirken: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Akşam vardiyası","Günün son kabul işleminde: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Erken teslimat","Araç randevudan erken geldiğinde: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Sabah ilk kabul","Vardiyanın ilk teslimatında: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Eksik belge","Teslimat evrakı eksik olduğunda: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Okuyucu arızası","Barkod okuyucu kullanılamadığında: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · İade dönüşü","Geri gelen ürünler ayrıştırılırken: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Manuel giriş","Barkod yerine elle kod yazılırken: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Eğitim uygulaması","Personel iş başında eğitim alırken: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Gün sonu raporu","Günün işlemleri raporlanırken: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Sayım günü","Depoda planlı sayım yapılırken: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Bayram öncesi","Sevkiyat hacmi artmışken: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Palet değişimi","Yük başka bir palete aktarılırken: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Kampanya dönemi","Ürün hareketi normalden hızlıyken: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Kalabalık saha","Yaya ve ekipman trafiği arttığında: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Hafta başı","Haftanın ilk sevkiyatında: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Alan doluluğu","Bekleme alanı dolmaya başladığında: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Dar koridor","Çalışma alanı daraldığında: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Vardiya devri","İş başka personele devredilirken: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Akşam vardiyası","Günün son kabul işleminde: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Erken teslimat","Araç randevudan erken geldiğinde: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Sabah ilk kabul","Vardiyanın ilk teslimatında: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Eksik belge","Teslimat evrakı eksik olduğunda: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Okuyucu arızası","Barkod okuyucu kullanılamadığında: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · İade dönüşü","Geri gelen ürünler ayrıştırılırken: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Manuel giriş","Barkod yerine elle kod yazılırken: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Eğitim uygulaması","Personel iş başında eğitim alırken: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Gün sonu raporu","Günün işlemleri raporlanırken: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Sayım günü","Depoda planlı sayım yapılırken: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Bayram öncesi","Sevkiyat hacmi artmışken: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Palet değişimi","Yük başka bir palete aktarılırken: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Kampanya dönemi","Ürün hareketi normalden hızlıyken: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Kalabalık saha","Yaya ve ekipman trafiği arttığında: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Hafta başı","Haftanın ilk sevkiyatında: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Alan doluluğu","Bekleme alanı dolmaya başladığında: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Dar koridor","Çalışma alanı daraldığında: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Vardiya devri","İş başka personele devredilirken: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Akşam vardiyası","Günün son kabul işleminde: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Erken teslimat","Araç randevudan erken geldiğinde: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Sabah ilk kabul","Vardiyanın ilk teslimatında: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Eksik belge","Teslimat evrakı eksik olduğunda: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Okuyucu arızası","Barkod okuyucu kullanılamadığında: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · İade dönüşü","Geri gelen ürünler ayrıştırılırken: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Manuel giriş","Barkod yerine elle kod yazılırken: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Eğitim uygulaması","Personel iş başında eğitim alırken: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Gün sonu raporu","Günün işlemleri raporlanırken: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Sayım günü","Depoda planlı sayım yapılırken: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Bayram öncesi","Sevkiyat hacmi artmışken: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Palet değişimi","Yük başka bir palete aktarılırken: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Kampanya dönemi","Ürün hareketi normalden hızlıyken: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Kalabalık saha","Yaya ve ekipman trafiği arttığında: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Hafta başı","Haftanın ilk sevkiyatında: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Alan doluluğu","Bekleme alanı dolmaya başladığında: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Dar koridor","Çalışma alanı daraldığında: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Vardiya devri","İş başka personele devredilirken: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Akşam vardiyası","Günün son kabul işleminde: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Erken teslimat","Araç randevudan erken geldiğinde: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Sabah ilk kabul","Vardiyanın ilk teslimatında: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Eksik belge","Teslimat evrakı eksik olduğunda: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Okuyucu arızası","Barkod okuyucu kullanılamadığında: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · İade dönüşü","Geri gelen ürünler ayrıştırılırken: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Manuel giriş","Barkod yerine elle kod yazılırken: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Eğitim uygulaması","Personel iş başında eğitim alırken: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Gün sonu raporu","Günün işlemleri raporlanırken: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Sayım günü","Depoda planlı sayım yapılırken: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Bayram öncesi","Sevkiyat hacmi artmışken: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Palet değişimi","Yük başka bir palete aktarılırken: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Kampanya dönemi","Ürün hareketi normalden hızlıyken: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Kalabalık saha","Yaya ve ekipman trafiği arttığında: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Hafta başı","Haftanın ilk sevkiyatında: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Alan doluluğu","Bekleme alanı dolmaya başladığında: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Dar koridor","Çalışma alanı daraldığında: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Vardiya devri","İş başka personele devredilirken: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Akşam vardiyası","Günün son kabul işleminde: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Erken teslimat","Araç randevudan erken geldiğinde: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Sabah ilk kabul","Vardiyanın ilk teslimatında: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Eksik belge","Teslimat evrakı eksik olduğunda: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Okuyucu arızası","Barkod okuyucu kullanılamadığında: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · İade dönüşü","Geri gelen ürünler ayrıştırılırken: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Manuel giriş","Barkod yerine elle kod yazılırken: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Eğitim uygulaması","Personel iş başında eğitim alırken: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Gün sonu raporu","Günün işlemleri raporlanırken: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Sayım günü","Depoda planlı sayım yapılırken: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Bayram öncesi","Sevkiyat hacmi artmışken: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Palet değişimi","Yük başka bir palete aktarılırken: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Kampanya dönemi","Ürün hareketi normalden hızlıyken: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Kalabalık saha","Yaya ve ekipman trafiği arttığında: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Hafta başı","Haftanın ilk sevkiyatında: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Alan doluluğu","Bekleme alanı dolmaya başladığında: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Dar koridor","Çalışma alanı daraldığında: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Vardiya devri","İş başka personele devredilirken: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Akşam vardiyası","Günün son kabul işleminde: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Erken teslimat","Araç randevudan erken geldiğinde: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Sabah ilk kabul","Vardiyanın ilk teslimatında: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Eksik belge","Teslimat evrakı eksik olduğunda: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Okuyucu arızası","Barkod okuyucu kullanılamadığında: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · İade dönüşü","Geri gelen ürünler ayrıştırılırken: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Manuel giriş","Barkod yerine elle kod yazılırken: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Eğitim uygulaması","Personel iş başında eğitim alırken: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Gün sonu raporu","Günün işlemleri raporlanırken: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Sayım günü","Depoda planlı sayım yapılırken: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Bayram öncesi","Sevkiyat hacmi artmışken: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Palet değişimi","Yük başka bir palete aktarılırken: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Kampanya dönemi","Ürün hareketi normalden hızlıyken: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Kalabalık saha","Yaya ve ekipman trafiği arttığında: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Hafta başı","Haftanın ilk sevkiyatında: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Alan doluluğu","Bekleme alanı dolmaya başladığında: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Dar koridor","Çalışma alanı daraldığında: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Vardiya devri","İş başka personele devredilirken: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Akşam vardiyası","Günün son kabul işleminde: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Erken teslimat","Araç randevudan erken geldiğinde: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Sabah ilk kabul","Vardiyanın ilk teslimatında: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Eksik belge","Teslimat evrakı eksik olduğunda: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Okuyucu arızası","Barkod okuyucu kullanılamadığında: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · İade dönüşü","Geri gelen ürünler ayrıştırılırken: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Manuel giriş","Barkod yerine elle kod yazılırken: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Eğitim uygulaması","Personel iş başında eğitim alırken: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Gün sonu raporu","Günün işlemleri raporlanırken: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Sayım günü","Depoda planlı sayım yapılırken: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Bayram öncesi","Sevkiyat hacmi artmışken: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Palet değişimi","Yük başka bir palete aktarılırken: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Kampanya dönemi","Ürün hareketi normalden hızlıyken: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Kalabalık saha","Yaya ve ekipman trafiği arttığında: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Hafta başı","Haftanın ilk sevkiyatında: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Alan doluluğu","Bekleme alanı dolmaya başladığında: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Dar koridor","Çalışma alanı daraldığında: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Vardiya devri","İş başka personele devredilirken: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Akşam vardiyası","Günün son kabul işleminde: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Erken teslimat","Araç randevudan erken geldiğinde: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Sabah ilk kabul","Vardiyanın ilk teslimatında: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Eksik belge","Teslimat evrakı eksik olduğunda: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Okuyucu arızası","Barkod okuyucu kullanılamadığında: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · İade dönüşü","Geri gelen ürünler ayrıştırılırken: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Manuel giriş","Barkod yerine elle kod yazılırken: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Eğitim uygulaması","Personel iş başında eğitim alırken: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Gün sonu raporu","Günün işlemleri raporlanırken: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Sayım günü","Depoda planlı sayım yapılırken: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Bayram öncesi","Sevkiyat hacmi artmışken: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Palet değişimi","Yük başka bir palete aktarılırken: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Kampanya dönemi","Ürün hareketi normalden hızlıyken: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Kalabalık saha","Yaya ve ekipman trafiği arttığında: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Hafta başı","Haftanın ilk sevkiyatında: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Alan doluluğu","Bekleme alanı dolmaya başladığında: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Dar koridor","Çalışma alanı daraldığında: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Vardiya devri","İş başka personele devredilirken: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Akşam vardiyası","Günün son kabul işleminde: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Erken teslimat","Araç randevudan erken geldiğinde: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Sabah ilk kabul","Vardiyanın ilk teslimatında: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Eksik belge","Teslimat evrakı eksik olduğunda: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Okuyucu arızası","Barkod okuyucu kullanılamadığında: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · İade dönüşü","Geri gelen ürünler ayrıştırılırken: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Manuel giriş","Barkod yerine elle kod yazılırken: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Eğitim uygulaması","Personel iş başında eğitim alırken: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Gün sonu raporu","Günün işlemleri raporlanırken: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Sayım günü","Depoda planlı sayım yapılırken: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Bayram öncesi","Sevkiyat hacmi artmışken: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Palet değişimi","Yük başka bir palete aktarılırken: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Kampanya dönemi","Ürün hareketi normalden hızlıyken: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Kalabalık saha","Yaya ve ekipman trafiği arttığında: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Hafta başı","Haftanın ilk sevkiyatında: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Alan doluluğu","Bekleme alanı dolmaya başladığında: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Dar koridor","Çalışma alanı daraldığında: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Vardiya devri","İş başka personele devredilirken: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Akşam vardiyası","Günün son kabul işleminde: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Erken teslimat","Araç randevudan erken geldiğinde: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Sabah ilk kabul","Vardiyanın ilk teslimatında: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Eksik belge","Teslimat evrakı eksik olduğunda: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Okuyucu arızası","Barkod okuyucu kullanılamadığında: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · İade dönüşü","Geri gelen ürünler ayrıştırılırken: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Manuel giriş","Barkod yerine elle kod yazılırken: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Eğitim uygulaması","Personel iş başında eğitim alırken: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Gün sonu raporu","Günün işlemleri raporlanırken: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Sayım günü","Depoda planlı sayım yapılırken: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Bayram öncesi","Sevkiyat hacmi artmışken: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Palet değişimi","Yük başka bir palete aktarılırken: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Kampanya dönemi","Ürün hareketi normalden hızlıyken: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Kalabalık saha","Yaya ve ekipman trafiği arttığında: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Hafta başı","Haftanın ilk sevkiyatında: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Alan doluluğu","Bekleme alanı dolmaya başladığında: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Dar koridor","Çalışma alanı daraldığında: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Vardiya devri","İş başka personele devredilirken: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Akşam vardiyası","Günün son kabul işleminde: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Erken teslimat","Araç randevudan erken geldiğinde: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Sabah ilk kabul","Vardiyanın ilk teslimatında: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Eksik belge","Teslimat evrakı eksik olduğunda: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Okuyucu arızası","Barkod okuyucu kullanılamadığında: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · İade dönüşü","Geri gelen ürünler ayrıştırılırken: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Manuel giriş","Barkod yerine elle kod yazılırken: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Eğitim uygulaması","Personel iş başında eğitim alırken: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Gün sonu raporu","Günün işlemleri raporlanırken: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Sayım günü","Depoda planlı sayım yapılırken: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Bayram öncesi","Sevkiyat hacmi artmışken: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Palet değişimi","Yük başka bir palete aktarılırken: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Kampanya dönemi","Ürün hareketi normalden hızlıyken: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Kalabalık saha","Yaya ve ekipman trafiği arttığında: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Hafta başı","Haftanın ilk sevkiyatında: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Alan doluluğu","Bekleme alanı dolmaya başladığında: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Dar koridor","Çalışma alanı daraldığında: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Vardiya devri","İş başka personele devredilirken: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Akşam vardiyası","Günün son kabul işleminde: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Erken teslimat","Araç randevudan erken geldiğinde: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Sabah ilk kabul","Vardiyanın ilk teslimatında: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Eksik belge","Teslimat evrakı eksik olduğunda: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Okuyucu arızası","Barkod okuyucu kullanılamadığında: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · İade dönüşü","Geri gelen ürünler ayrıştırılırken: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Manuel giriş","Barkod yerine elle kod yazılırken: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Eğitim uygulaması","Personel iş başında eğitim alırken: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Gün sonu raporu","Günün işlemleri raporlanırken: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Sayım günü","Depoda planlı sayım yapılırken: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Bayram öncesi","Sevkiyat hacmi artmışken: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Palet değişimi","Yük başka bir palete aktarılırken: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Kampanya dönemi","Ürün hareketi normalden hızlıyken: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Kalabalık saha","Yaya ve ekipman trafiği arttığında: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Hafta başı","Haftanın ilk sevkiyatında: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Alan doluluğu","Bekleme alanı dolmaya başladığında: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Dar koridor","Çalışma alanı daraldığında: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Vardiya devri","İş başka personele devredilirken: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Akşam vardiyası","Günün son kabul işleminde: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Erken teslimat","Araç randevudan erken geldiğinde: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Sabah ilk kabul","Vardiyanın ilk teslimatında: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Eksik belge","Teslimat evrakı eksik olduğunda: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Okuyucu arızası","Barkod okuyucu kullanılamadığında: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · İade dönüşü","Geri gelen ürünler ayrıştırılırken: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Manuel giriş","Barkod yerine elle kod yazılırken: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Eğitim uygulaması","Personel iş başında eğitim alırken: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Gün sonu raporu","Günün işlemleri raporlanırken: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Sayım günü","Depoda planlı sayım yapılırken: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Bayram öncesi","Sevkiyat hacmi artmışken: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Palet değişimi","Yük başka bir palete aktarılırken: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Kampanya dönemi","Ürün hareketi normalden hızlıyken: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Kalabalık saha","Yaya ve ekipman trafiği arttığında: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Hafta başı","Haftanın ilk sevkiyatında: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Alan doluluğu","Bekleme alanı dolmaya başladığında: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Dar koridor","Çalışma alanı daraldığında: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Vardiya devri","İş başka personele devredilirken: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Akşam vardiyası","Günün son kabul işleminde: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Erken teslimat","Araç randevudan erken geldiğinde: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Sabah ilk kabul","Vardiyanın ilk teslimatında: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Eksik belge","Teslimat evrakı eksik olduğunda: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Okuyucu arızası","Barkod okuyucu kullanılamadığında: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · İade dönüşü","Geri gelen ürünler ayrıştırılırken: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Manuel giriş","Barkod yerine elle kod yazılırken: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Eğitim uygulaması","Personel iş başında eğitim alırken: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Gün sonu raporu","Günün işlemleri raporlanırken: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Sayım günü","Depoda planlı sayım yapılırken: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Bayram öncesi","Sevkiyat hacmi artmışken: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Palet değişimi","Yük başka bir palete aktarılırken: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Kampanya dönemi","Ürün hareketi normalden hızlıyken: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Kalabalık saha","Yaya ve ekipman trafiği arttığında: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Hafta başı","Haftanın ilk sevkiyatında: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Alan doluluğu","Bekleme alanı dolmaya başladığında: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Dar koridor","Çalışma alanı daraldığında: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Vardiya devri","İş başka personele devredilirken: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Akşam vardiyası","Günün son kabul işleminde: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Erken teslimat","Araç randevudan erken geldiğinde: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Sabah ilk kabul","Vardiyanın ilk teslimatında: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Eksik belge","Teslimat evrakı eksik olduğunda: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Okuyucu arızası","Barkod okuyucu kullanılamadığında: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · İade dönüşü","Geri gelen ürünler ayrıştırılırken: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Manuel giriş","Barkod yerine elle kod yazılırken: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Eğitim uygulaması","Personel iş başında eğitim alırken: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Gün sonu raporu","Günün işlemleri raporlanırken: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Sayım günü","Depoda planlı sayım yapılırken: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Bayram öncesi","Sevkiyat hacmi artmışken: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Palet değişimi","Yük başka bir palete aktarılırken: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Kampanya dönemi","Ürün hareketi normalden hızlıyken: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Kalabalık saha","Yaya ve ekipman trafiği arttığında: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Hafta başı","Haftanın ilk sevkiyatında: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Alan doluluğu","Bekleme alanı dolmaya başladığında: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Dar koridor","Çalışma alanı daraldığında: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Vardiya devri","İş başka personele devredilirken: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Akşam vardiyası","Günün son kabul işleminde: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Erken teslimat","Araç randevudan erken geldiğinde: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Sabah ilk kabul","Vardiyanın ilk teslimatında: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Eksik belge","Teslimat evrakı eksik olduğunda: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Okuyucu arızası","Barkod okuyucu kullanılamadığında: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · İade dönüşü","Geri gelen ürünler ayrıştırılırken: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Manuel giriş","Barkod yerine elle kod yazılırken: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Eğitim uygulaması","Personel iş başında eğitim alırken: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Gün sonu raporu","Günün işlemleri raporlanırken: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Sayım günü","Depoda planlı sayım yapılırken: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Bayram öncesi","Sevkiyat hacmi artmışken: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Palet değişimi","Yük başka bir palete aktarılırken: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Kampanya dönemi","Ürün hareketi normalden hızlıyken: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Kalabalık saha","Yaya ve ekipman trafiği arttığında: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Hafta başı","Haftanın ilk sevkiyatında: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Alan doluluğu","Bekleme alanı dolmaya başladığında: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Dar koridor","Çalışma alanı daraldığında: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Vardiya devri","İş başka personele devredilirken: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Akşam vardiyası","Günün son kabul işleminde: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Erken teslimat","Araç randevudan erken geldiğinde: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Sabah ilk kabul","Vardiyanın ilk teslimatında: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Eksik belge","Teslimat evrakı eksik olduğunda: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Okuyucu arızası","Barkod okuyucu kullanılamadığında: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · İade dönüşü","Geri gelen ürünler ayrıştırılırken: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Manuel giriş","Barkod yerine elle kod yazılırken: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Eğitim uygulaması","Personel iş başında eğitim alırken: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Gün sonu raporu","Günün işlemleri raporlanırken: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Sayım günü","Depoda planlı sayım yapılırken: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Bayram öncesi","Sevkiyat hacmi artmışken: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Palet değişimi","Yük başka bir palete aktarılırken: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Kampanya dönemi","Ürün hareketi normalden hızlıyken: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Kalabalık saha","Yaya ve ekipman trafiği arttığında: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Hafta başı","Haftanın ilk sevkiyatında: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Alan doluluğu","Bekleme alanı dolmaya başladığında: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Dar koridor","Çalışma alanı daraldığında: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Vardiya devri","İş başka personele devredilirken: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Akşam vardiyası","Günün son kabul işleminde: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Erken teslimat","Araç randevudan erken geldiğinde: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Sabah ilk kabul","Vardiyanın ilk teslimatında: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Eksik belge","Teslimat evrakı eksik olduğunda: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Okuyucu arızası","Barkod okuyucu kullanılamadığında: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · İade dönüşü","Geri gelen ürünler ayrıştırılırken: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Manuel giriş","Barkod yerine elle kod yazılırken: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Eğitim uygulaması","Personel iş başında eğitim alırken: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Gün sonu raporu","Günün işlemleri raporlanırken: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Sayım günü","Depoda planlı sayım yapılırken: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Bayram öncesi","Sevkiyat hacmi artmışken: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Palet değişimi","Yük başka bir palete aktarılırken: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Kampanya dönemi","Ürün hareketi normalden hızlıyken: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Kalabalık saha","Yaya ve ekipman trafiği arttığında: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Hafta başı","Haftanın ilk sevkiyatında: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Alan doluluğu","Bekleme alanı dolmaya başladığında: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Dar koridor","Çalışma alanı daraldığında: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Vardiya devri","İş başka personele devredilirken: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Akşam vardiyası","Günün son kabul işleminde: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Erken teslimat","Araç randevudan erken geldiğinde: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Sabah ilk kabul","Vardiyanın ilk teslimatında: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Eksik belge","Teslimat evrakı eksik olduğunda: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Okuyucu arızası","Barkod okuyucu kullanılamadığında: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · İade dönüşü","Geri gelen ürünler ayrıştırılırken: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Manuel giriş","Barkod yerine elle kod yazılırken: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Eğitim uygulaması","Personel iş başında eğitim alırken: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Gün sonu raporu","Günün işlemleri raporlanırken: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Sayım günü","Depoda planlı sayım yapılırken: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Bayram öncesi","Sevkiyat hacmi artmışken: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Palet değişimi","Yük başka bir palete aktarılırken: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Kampanya dönemi","Ürün hareketi normalden hızlıyken: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Kalabalık saha","Yaya ve ekipman trafiği arttığında: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Hafta başı","Haftanın ilk sevkiyatında: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Alan doluluğu","Bekleme alanı dolmaya başladığında: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Dar koridor","Çalışma alanı daraldığında: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Vardiya devri","İş başka personele devredilirken: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Akşam vardiyası","Günün son kabul işleminde: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Erken teslimat","Araç randevudan erken geldiğinde: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Sabah ilk kabul","Vardiyanın ilk teslimatında: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Eksik belge","Teslimat evrakı eksik olduğunda: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Okuyucu arızası","Barkod okuyucu kullanılamadığında: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · İade dönüşü","Geri gelen ürünler ayrıştırılırken: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Manuel giriş","Barkod yerine elle kod yazılırken: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Eğitim uygulaması","Personel iş başında eğitim alırken: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Gün sonu raporu","Günün işlemleri raporlanırken: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Sayım günü","Depoda planlı sayım yapılırken: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Bayram öncesi","Sevkiyat hacmi artmışken: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Palet değişimi","Yük başka bir palete aktarılırken: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Kampanya dönemi","Ürün hareketi normalden hızlıyken: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Kalabalık saha","Yaya ve ekipman trafiği arttığında: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Hafta başı","Haftanın ilk sevkiyatında: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Alan doluluğu","Bekleme alanı dolmaya başladığında: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Dar koridor","Çalışma alanı daraldığında: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Vardiya devri","İş başka personele devredilirken: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Akşam vardiyası","Günün son kabul işleminde: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Erken teslimat","Araç randevudan erken geldiğinde: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Sabah ilk kabul","Vardiyanın ilk teslimatında: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Eksik belge","Teslimat evrakı eksik olduğunda: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Okuyucu arızası","Barkod okuyucu kullanılamadığında: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · İade dönüşü","Geri gelen ürünler ayrıştırılırken: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Manuel giriş","Barkod yerine elle kod yazılırken: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Eğitim uygulaması","Personel iş başında eğitim alırken: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Gün sonu raporu","Günün işlemleri raporlanırken: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Sayım günü","Depoda planlı sayım yapılırken: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Bayram öncesi","Sevkiyat hacmi artmışken: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Palet değişimi","Yük başka bir palete aktarılırken: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Kampanya dönemi","Ürün hareketi normalden hızlıyken: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Kalabalık saha","Yaya ve ekipman trafiği arttığında: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Hafta başı","Haftanın ilk sevkiyatında: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Alan doluluğu","Bekleme alanı dolmaya başladığında: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Dar koridor","Çalışma alanı daraldığında: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Vardiya devri","İş başka personele devredilirken: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Akşam vardiyası","Günün son kabul işleminde: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Erken teslimat","Araç randevudan erken geldiğinde: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Sabah ilk kabul","Vardiyanın ilk teslimatında: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Eksik belge","Teslimat evrakı eksik olduğunda: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Okuyucu arızası","Barkod okuyucu kullanılamadığında: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · İade dönüşü","Geri gelen ürünler ayrıştırılırken: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Manuel giriş","Barkod yerine elle kod yazılırken: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Eğitim uygulaması","Personel iş başında eğitim alırken: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Gün sonu raporu","Günün işlemleri raporlanırken: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Sayım günü","Depoda planlı sayım yapılırken: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Bayram öncesi","Sevkiyat hacmi artmışken: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Palet değişimi","Yük başka bir palete aktarılırken: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Kampanya dönemi","Ürün hareketi normalden hızlıyken: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Kalabalık saha","Yaya ve ekipman trafiği arttığında: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Hafta başı","Haftanın ilk sevkiyatında: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Alan doluluğu","Bekleme alanı dolmaya başladığında: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Dar koridor","Çalışma alanı daraldığında: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Vardiya devri","İş başka personele devredilirken: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Akşam vardiyası","Günün son kabul işleminde: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Erken teslimat","Araç randevudan erken geldiğinde: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Sabah ilk kabul","Vardiyanın ilk teslimatında: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Eksik belge","Teslimat evrakı eksik olduğunda: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Okuyucu arızası","Barkod okuyucu kullanılamadığında: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · İade dönüşü","Geri gelen ürünler ayrıştırılırken: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Manuel giriş","Barkod yerine elle kod yazılırken: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Eğitim uygulaması","Personel iş başında eğitim alırken: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Gün sonu raporu","Günün işlemleri raporlanırken: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Sayım günü","Depoda planlı sayım yapılırken: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Bayram öncesi","Sevkiyat hacmi artmışken: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Palet değişimi","Yük başka bir palete aktarılırken: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Kampanya dönemi","Ürün hareketi normalden hızlıyken: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Kalabalık saha","Yaya ve ekipman trafiği arttığında: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Hafta başı","Haftanın ilk sevkiyatında: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Alan doluluğu","Bekleme alanı dolmaya başladığında: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Dar koridor","Çalışma alanı daraldığında: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Vardiya devri","İş başka personele devredilirken: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Akşam vardiyası","Günün son kabul işleminde: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Erken teslimat","Araç randevudan erken geldiğinde: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Sabah ilk kabul","Vardiyanın ilk teslimatında: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Eksik belge","Teslimat evrakı eksik olduğunda: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Okuyucu arızası","Barkod okuyucu kullanılamadığında: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · İade dönüşü","Geri gelen ürünler ayrıştırılırken: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Manuel giriş","Barkod yerine elle kod yazılırken: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Eğitim uygulaması","Personel iş başında eğitim alırken: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Gün sonu raporu","Günün işlemleri raporlanırken: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Sayım günü","Depoda planlı sayım yapılırken: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Bayram öncesi","Sevkiyat hacmi artmışken: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Palet değişimi","Yük başka bir palete aktarılırken: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Kampanya dönemi","Ürün hareketi normalden hızlıyken: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Kalabalık saha","Yaya ve ekipman trafiği arttığında: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Hafta başı","Haftanın ilk sevkiyatında: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Alan doluluğu","Bekleme alanı dolmaya başladığında: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Dar koridor","Çalışma alanı daraldığında: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Vardiya devri","İş başka personele devredilirken: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Akşam vardiyası","Günün son kabul işleminde: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Erken teslimat","Araç randevudan erken geldiğinde: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Sabah ilk kabul","Vardiyanın ilk teslimatında: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Eksik belge","Teslimat evrakı eksik olduğunda: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Okuyucu arızası","Barkod okuyucu kullanılamadığında: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · İade dönüşü","Geri gelen ürünler ayrıştırılırken: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Manuel giriş","Barkod yerine elle kod yazılırken: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Eğitim uygulaması","Personel iş başında eğitim alırken: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Gün sonu raporu","Günün işlemleri raporlanırken: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Sayım günü","Depoda planlı sayım yapılırken: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Bayram öncesi","Sevkiyat hacmi artmışken: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Palet değişimi","Yük başka bir palete aktarılırken: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Kampanya dönemi","Ürün hareketi normalden hızlıyken: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Kalabalık saha","Yaya ve ekipman trafiği arttığında: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Hafta başı","Haftanın ilk sevkiyatında: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Alan doluluğu","Bekleme alanı dolmaya başladığında: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Dar koridor","Çalışma alanı daraldığında: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Vardiya devri","İş başka personele devredilirken: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Akşam vardiyası","Günün son kabul işleminde: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Erken teslimat","Araç randevudan erken geldiğinde: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Sabah ilk kabul","Vardiyanın ilk teslimatında: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Eksik belge","Teslimat evrakı eksik olduğunda: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Okuyucu arızası","Barkod okuyucu kullanılamadığında: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · İade dönüşü","Geri gelen ürünler ayrıştırılırken: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Manuel giriş","Barkod yerine elle kod yazılırken: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Eğitim uygulaması","Personel iş başında eğitim alırken: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Gün sonu raporu","Günün işlemleri raporlanırken: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Sayım günü","Depoda planlı sayım yapılırken: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Bayram öncesi","Sevkiyat hacmi artmışken: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Palet değişimi","Yük başka bir palete aktarılırken: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Kampanya dönemi","Ürün hareketi normalden hızlıyken: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Kalabalık saha","Yaya ve ekipman trafiği arttığında: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Hafta başı","Haftanın ilk sevkiyatında: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Alan doluluğu","Bekleme alanı dolmaya başladığında: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Dar koridor","Çalışma alanı daraldığında: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Vardiya devri","İş başka personele devredilirken: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Akşam vardiyası","Günün son kabul işleminde: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Erken teslimat","Araç randevudan erken geldiğinde: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Sabah ilk kabul","Vardiyanın ilk teslimatında: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Eksik belge","Teslimat evrakı eksik olduğunda: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Okuyucu arızası","Barkod okuyucu kullanılamadığında: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · İade dönüşü","Geri gelen ürünler ayrıştırılırken: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Manuel giriş","Barkod yerine elle kod yazılırken: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Eğitim uygulaması","Personel iş başında eğitim alırken: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Gün sonu raporu","Günün işlemleri raporlanırken: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Sayım günü","Depoda planlı sayım yapılırken: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Bayram öncesi","Sevkiyat hacmi artmışken: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Palet değişimi","Yük başka bir palete aktarılırken: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Kampanya dönemi","Ürün hareketi normalden hızlıyken: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Kalabalık saha","Yaya ve ekipman trafiği arttığında: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Hafta başı","Haftanın ilk sevkiyatında: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Alan doluluğu","Bekleme alanı dolmaya başladığında: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Dar koridor","Çalışma alanı daraldığında: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Vardiya devri","İş başka personele devredilirken: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Akşam vardiyası","Günün son kabul işleminde: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Erken teslimat","Araç randevudan erken geldiğinde: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Sabah ilk kabul","Vardiyanın ilk teslimatında: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Eksik belge","Teslimat evrakı eksik olduğunda: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Okuyucu arızası","Barkod okuyucu kullanılamadığında: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · İade dönüşü","Geri gelen ürünler ayrıştırılırken: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Manuel giriş","Barkod yerine elle kod yazılırken: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Eğitim uygulaması","Personel iş başında eğitim alırken: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Gün sonu raporu","Günün işlemleri raporlanırken: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Sayım günü","Depoda planlı sayım yapılırken: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Bayram öncesi","Sevkiyat hacmi artmışken: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Palet değişimi","Yük başka bir palete aktarılırken: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Kampanya dönemi","Ürün hareketi normalden hızlıyken: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Kalabalık saha","Yaya ve ekipman trafiği arttığında: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Hafta başı","Haftanın ilk sevkiyatında: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Alan doluluğu","Bekleme alanı dolmaya başladığında: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Dar koridor","Çalışma alanı daraldığında: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Vardiya devri","İş başka personele devredilirken: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Akşam vardiyası","Günün son kabul işleminde: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Erken teslimat","Araç randevudan erken geldiğinde: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Sabah ilk kabul","Vardiyanın ilk teslimatında: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Eksik belge","Teslimat evrakı eksik olduğunda: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Okuyucu arızası","Barkod okuyucu kullanılamadığında: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · İade dönüşü","Geri gelen ürünler ayrıştırılırken: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Manuel giriş","Barkod yerine elle kod yazılırken: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Eğitim uygulaması","Personel iş başında eğitim alırken: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Gün sonu raporu","Günün işlemleri raporlanırken: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Sayım günü","Depoda planlı sayım yapılırken: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Bayram öncesi","Sevkiyat hacmi artmışken: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Palet değişimi","Yük başka bir palete aktarılırken: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Kampanya dönemi","Ürün hareketi normalden hızlıyken: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Kalabalık saha","Yaya ve ekipman trafiği arttığında: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Hafta başı","Haftanın ilk sevkiyatında: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Alan doluluğu","Bekleme alanı dolmaya başladığında: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Dar koridor","Çalışma alanı daraldığında: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Vardiya devri","İş başka personele devredilirken: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Akşam vardiyası","Günün son kabul işleminde: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Erken teslimat","Araç randevudan erken geldiğinde: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Sabah ilk kabul","Vardiyanın ilk teslimatında: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Eksik belge","Teslimat evrakı eksik olduğunda: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Okuyucu arızası","Barkod okuyucu kullanılamadığında: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · İade dönüşü","Geri gelen ürünler ayrıştırılırken: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Manuel giriş","Barkod yerine elle kod yazılırken: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Eğitim uygulaması","Personel iş başında eğitim alırken: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Gün sonu raporu","Günün işlemleri raporlanırken: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Sayım günü","Depoda planlı sayım yapılırken: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Bayram öncesi","Sevkiyat hacmi artmışken: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Palet değişimi","Yük başka bir palete aktarılırken: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Kampanya dönemi","Ürün hareketi normalden hızlıyken: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Kalabalık saha","Yaya ve ekipman trafiği arttığında: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Hafta başı","Haftanın ilk sevkiyatında: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Alan doluluğu","Bekleme alanı dolmaya başladığında: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Dar koridor","Çalışma alanı daraldığında: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Vardiya devri","İş başka personele devredilirken: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Akşam vardiyası","Günün son kabul işleminde: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Erken teslimat","Araç randevudan erken geldiğinde: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Sabah ilk kabul","Vardiyanın ilk teslimatında: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Eksik belge","Teslimat evrakı eksik olduğunda: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Okuyucu arızası","Barkod okuyucu kullanılamadığında: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · İade dönüşü","Geri gelen ürünler ayrıştırılırken: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Manuel giriş","Barkod yerine elle kod yazılırken: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Eğitim uygulaması","Personel iş başında eğitim alırken: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Gün sonu raporu","Günün işlemleri raporlanırken: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Sayım günü","Depoda planlı sayım yapılırken: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Bayram öncesi","Sevkiyat hacmi artmışken: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Palet değişimi","Yük başka bir palete aktarılırken: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Kampanya dönemi","Ürün hareketi normalden hızlıyken: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Kalabalık saha","Yaya ve ekipman trafiği arttığında: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Hafta başı","Haftanın ilk sevkiyatında: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Alan doluluğu","Bekleme alanı dolmaya başladığında: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Dar koridor","Çalışma alanı daraldığında: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Vardiya devri","İş başka personele devredilirken: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Akşam vardiyası","Günün son kabul işleminde: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Erken teslimat","Araç randevudan erken geldiğinde: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Sabah ilk kabul","Vardiyanın ilk teslimatında: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Eksik belge","Teslimat evrakı eksik olduğunda: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Okuyucu arızası","Barkod okuyucu kullanılamadığında: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · İade dönüşü","Geri gelen ürünler ayrıştırılırken: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Manuel giriş","Barkod yerine elle kod yazılırken: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Eğitim uygulaması","Personel iş başında eğitim alırken: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Gün sonu raporu","Günün işlemleri raporlanırken: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Sayım günü","Depoda planlı sayım yapılırken: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Bayram öncesi","Sevkiyat hacmi artmışken: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Palet değişimi","Yük başka bir palete aktarılırken: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Kampanya dönemi","Ürün hareketi normalden hızlıyken: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Kalabalık saha","Yaya ve ekipman trafiği arttığında: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Hafta başı","Haftanın ilk sevkiyatında: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Alan doluluğu","Bekleme alanı dolmaya başladığında: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Dar koridor","Çalışma alanı daraldığında: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Vardiya devri","İş başka personele devredilirken: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Akşam vardiyası","Günün son kabul işleminde: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Erken teslimat","Araç randevudan erken geldiğinde: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Sabah ilk kabul","Vardiyanın ilk teslimatında: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Eksik belge","Teslimat evrakı eksik olduğunda: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Okuyucu arızası","Barkod okuyucu kullanılamadığında: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · İade dönüşü","Geri gelen ürünler ayrıştırılırken: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Manuel giriş","Barkod yerine elle kod yazılırken: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Eğitim uygulaması","Personel iş başında eğitim alırken: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Gün sonu raporu","Günün işlemleri raporlanırken: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Sayım günü","Depoda planlı sayım yapılırken: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Bayram öncesi","Sevkiyat hacmi artmışken: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Palet değişimi","Yük başka bir palete aktarılırken: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Kampanya dönemi","Ürün hareketi normalden hızlıyken: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Kalabalık saha","Yaya ve ekipman trafiği arttığında: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Hafta başı","Haftanın ilk sevkiyatında: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Alan doluluğu","Bekleme alanı dolmaya başladığında: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Dar koridor","Çalışma alanı daraldığında: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Vardiya devri","İş başka personele devredilirken: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Akşam vardiyası","Günün son kabul işleminde: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Erken teslimat","Araç randevudan erken geldiğinde: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Sabah ilk kabul","Vardiyanın ilk teslimatında: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Eksik belge","Teslimat evrakı eksik olduğunda: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Okuyucu arızası","Barkod okuyucu kullanılamadığında: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · İade dönüşü","Geri gelen ürünler ayrıştırılırken: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Manuel giriş","Barkod yerine elle kod yazılırken: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Eğitim uygulaması","Personel iş başında eğitim alırken: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Gün sonu raporu","Günün işlemleri raporlanırken: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Sayım günü","Depoda planlı sayım yapılırken: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Bayram öncesi","Sevkiyat hacmi artmışken: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Palet değişimi","Yük başka bir palete aktarılırken: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Kampanya dönemi","Ürün hareketi normalden hızlıyken: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Kalabalık saha","Yaya ve ekipman trafiği arttığında: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Hafta başı","Haftanın ilk sevkiyatında: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Alan doluluğu","Bekleme alanı dolmaya başladığında: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Dar koridor","Çalışma alanı daraldığında: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Vardiya devri","İş başka personele devredilirken: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Akşam vardiyası","Günün son kabul işleminde: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Erken teslimat","Araç randevudan erken geldiğinde: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Sabah ilk kabul","Vardiyanın ilk teslimatında: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Eksik belge","Teslimat evrakı eksik olduğunda: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Okuyucu arızası","Barkod okuyucu kullanılamadığında: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · İade dönüşü","Geri gelen ürünler ayrıştırılırken: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Manuel giriş","Barkod yerine elle kod yazılırken: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Eğitim uygulaması","Personel iş başında eğitim alırken: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Gün sonu raporu","Günün işlemleri raporlanırken: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Sayım günü","Depoda planlı sayım yapılırken: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Bayram öncesi","Sevkiyat hacmi artmışken: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Palet değişimi","Yük başka bir palete aktarılırken: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Kampanya dönemi","Ürün hareketi normalden hızlıyken: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Kalabalık saha","Yaya ve ekipman trafiği arttığında: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Hafta başı","Haftanın ilk sevkiyatında: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Alan doluluğu","Bekleme alanı dolmaya başladığında: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Dar koridor","Çalışma alanı daraldığında: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Vardiya devri","İş başka personele devredilirken: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Akşam vardiyası","Günün son kabul işleminde: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Erken teslimat","Araç randevudan erken geldiğinde: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Sabah ilk kabul","Vardiyanın ilk teslimatında: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Eksik belge","Teslimat evrakı eksik olduğunda: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Okuyucu arızası","Barkod okuyucu kullanılamadığında: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · İade dönüşü","Geri gelen ürünler ayrıştırılırken: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Manuel giriş","Barkod yerine elle kod yazılırken: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Eğitim uygulaması","Personel iş başında eğitim alırken: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Gün sonu raporu","Günün işlemleri raporlanırken: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Sayım günü","Depoda planlı sayım yapılırken: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Bayram öncesi","Sevkiyat hacmi artmışken: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Palet değişimi","Yük başka bir palete aktarılırken: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Kampanya dönemi","Ürün hareketi normalden hızlıyken: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Kalabalık saha","Yaya ve ekipman trafiği arttığında: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Hafta başı","Haftanın ilk sevkiyatında: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Alan doluluğu","Bekleme alanı dolmaya başladığında: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Dar koridor","Çalışma alanı daraldığında: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Vardiya devri","İş başka personele devredilirken: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Akşam vardiyası","Günün son kabul işleminde: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Erken teslimat","Araç randevudan erken geldiğinde: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Sabah ilk kabul","Vardiyanın ilk teslimatında: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Eksik belge","Teslimat evrakı eksik olduğunda: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Okuyucu arızası","Barkod okuyucu kullanılamadığında: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · İade dönüşü","Geri gelen ürünler ayrıştırılırken: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Manuel giriş","Barkod yerine elle kod yazılırken: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Eğitim uygulaması","Personel iş başında eğitim alırken: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Gün sonu raporu","Günün işlemleri raporlanırken: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Sayım günü","Depoda planlı sayım yapılırken: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Bayram öncesi","Sevkiyat hacmi artmışken: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Palet değişimi","Yük başka bir palete aktarılırken: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Kampanya dönemi","Ürün hareketi normalden hızlıyken: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Kalabalık saha","Yaya ve ekipman trafiği arttığında: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Hafta başı","Haftanın ilk sevkiyatında: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Alan doluluğu","Bekleme alanı dolmaya başladığında: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Dar koridor","Çalışma alanı daraldığında: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Vardiya devri","İş başka personele devredilirken: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Akşam vardiyası","Günün son kabul işleminde: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Erken teslimat","Araç randevudan erken geldiğinde: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Sabah ilk kabul","Vardiyanın ilk teslimatında: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Eksik belge","Teslimat evrakı eksik olduğunda: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Okuyucu arızası","Barkod okuyucu kullanılamadığında: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · İade dönüşü","Geri gelen ürünler ayrıştırılırken: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Manuel giriş","Barkod yerine elle kod yazılırken: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Eğitim uygulaması","Personel iş başında eğitim alırken: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Gün sonu raporu","Günün işlemleri raporlanırken: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Sayım günü","Depoda planlı sayım yapılırken: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Bayram öncesi","Sevkiyat hacmi artmışken: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Palet değişimi","Yük başka bir palete aktarılırken: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Kampanya dönemi","Ürün hareketi normalden hızlıyken: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Kalabalık saha","Yaya ve ekipman trafiği arttığında: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Hafta başı","Haftanın ilk sevkiyatında: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Alan doluluğu","Bekleme alanı dolmaya başladığında: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Dar koridor","Çalışma alanı daraldığında: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Vardiya devri","İş başka personele devredilirken: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Akşam vardiyası","Günün son kabul işleminde: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Erken teslimat","Araç randevudan erken geldiğinde: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Sabah ilk kabul","Vardiyanın ilk teslimatında: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Eksik belge","Teslimat evrakı eksik olduğunda: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Okuyucu arızası","Barkod okuyucu kullanılamadığında: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · İade dönüşü","Geri gelen ürünler ayrıştırılırken: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Manuel giriş","Barkod yerine elle kod yazılırken: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Eğitim uygulaması","Personel iş başında eğitim alırken: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Gün sonu raporu","Günün işlemleri raporlanırken: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Sayım günü","Depoda planlı sayım yapılırken: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Bayram öncesi","Sevkiyat hacmi artmışken: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Palet değişimi","Yük başka bir palete aktarılırken: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Kampanya dönemi","Ürün hareketi normalden hızlıyken: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Kalabalık saha","Yaya ve ekipman trafiği arttığında: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Hafta başı","Haftanın ilk sevkiyatında: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Alan doluluğu","Bekleme alanı dolmaya başladığında: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Dar koridor","Çalışma alanı daraldığında: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Vardiya devri","İş başka personele devredilirken: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Akşam vardiyası","Günün son kabul işleminde: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Erken teslimat","Araç randevudan erken geldiğinde: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Sabah ilk kabul","Vardiyanın ilk teslimatında: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Eksik belge","Teslimat evrakı eksik olduğunda: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Okuyucu arızası","Barkod okuyucu kullanılamadığında: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · İade dönüşü","Geri gelen ürünler ayrıştırılırken: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Manuel giriş","Barkod yerine elle kod yazılırken: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Eğitim uygulaması","Personel iş başında eğitim alırken: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Gün sonu raporu","Günün işlemleri raporlanırken: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Sayım günü","Depoda planlı sayım yapılırken: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Bayram öncesi","Sevkiyat hacmi artmışken: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Palet değişimi","Yük başka bir palete aktarılırken: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Kampanya dönemi","Ürün hareketi normalden hızlıyken: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Kalabalık saha","Yaya ve ekipman trafiği arttığında: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Hafta başı","Haftanın ilk sevkiyatında: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Alan doluluğu","Bekleme alanı dolmaya başladığında: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Dar koridor","Çalışma alanı daraldığında: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Vardiya devri","İş başka personele devredilirken: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Akşam vardiyası","Günün son kabul işleminde: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Erken teslimat","Araç randevudan erken geldiğinde: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Sabah ilk kabul","Vardiyanın ilk teslimatında: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Eksik belge","Teslimat evrakı eksik olduğunda: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Okuyucu arızası","Barkod okuyucu kullanılamadığında: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · İade dönüşü","Geri gelen ürünler ayrıştırılırken: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Manuel giriş","Barkod yerine elle kod yazılırken: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Eğitim uygulaması","Personel iş başında eğitim alırken: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Gün sonu raporu","Günün işlemleri raporlanırken: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Sayım günü","Depoda planlı sayım yapılırken: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Bayram öncesi","Sevkiyat hacmi artmışken: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Palet değişimi","Yük başka bir palete aktarılırken: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Kampanya dönemi","Ürün hareketi normalden hızlıyken: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Kalabalık saha","Yaya ve ekipman trafiği arttığında: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Hafta başı","Haftanın ilk sevkiyatında: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Alan doluluğu","Bekleme alanı dolmaya başladığında: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Dar koridor","Çalışma alanı daraldığında: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Vardiya devri","İş başka personele devredilirken: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Akşam vardiyası","Günün son kabul işleminde: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Erken teslimat","Araç randevudan erken geldiğinde: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Sabah ilk kabul","Vardiyanın ilk teslimatında: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Eksik belge","Teslimat evrakı eksik olduğunda: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye kontrolü · Okuyucu arızası","Barkod okuyucu kullanılamadığında: teslim alınan ürünlerin kodunu, miktarını ve ambalaj durumunu irsaliyeyle karşılaştırın.","Farkları teslimat kaydına işleyin; varsayımla miktar düzeltmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · İade dönüşü","Geri gelen ürünler ayrıştırılırken: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yaya yolları · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: forklift güzergâhlarıyla yaya geçişlerinin kontrolsüz kesişmesi çarpışma riskini artırır.","İşaretli geçişleri ve işletmenin trafik planını kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · Manuel giriş","Barkod yerine elle kod yazılırken: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Ambalaj bütünlüğü · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: ambalaj bütünlüğü bozulmuş ürünler için standart kabul işlemi her zaman uygun olmayabilir.","Ürünün niteliğine göre kalite biriminin değerlendirmesini isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tedarikçi referansı · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: tedarikçi ürün kodu şirket içi stok kodundan farklı olabilir.","Eşleştirmeyi onaylı ürün kataloğuyla yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Streç bütünlüğü · Eğitim uygulaması","Personel iş başında eğitim alırken: yetersiz streçleme taşıma sırasında kolilerin kaymasına neden olabilir.","Ambalajın yükü güvenle tuttuğunu doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Yabancı madde · Gün sonu raporu","Günün işlemleri raporlanırken: açık veya zarar görmüş ambalajlarda yabancı madde riski bulunabilir.","Şüpheli ürünleri kalite değerlendirmesine ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Döküntü müdahalesi · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: bilinmeyen sıvılara korumasız müdahale etmek tehlikeli olabilir.","Maddenin niteliğine uygun acil prosedürü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Sayım günü","Depoda planlı sayım yapılırken: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Kontrol listesi · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: kısa kontrol listeleri tekrarlanan görevlerde unutulan adımları azaltır.","Listeyi gerçek operasyon risklerine göre güncelleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Bayram öncesi","Sevkiyat hacmi artmışken: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Yanlış barkod eşleşmesi · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: bir barkod yanlış ürüne bağlanırsa sayım ve stok hareketleri hatalı kaydedilebilir.","Ürün kodu ve ürün adını eşleştirmeden önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Palet değişimi","Yük başka bir palete aktarılırken: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Kampanya dönemi","Ürün hareketi normalden hızlıyken: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet etiketleri · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: palet üzerindeki etiketin okunabilir olması yerleştirme ve sevkiyat hatalarını azaltır.","Etiketteki ürün ve miktar bilgilerini fiziksel yükle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tekrarlı ürün satırı · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: i̇rsaliyede aynı ürün birden fazla satırda bulunabilir.","Toplam miktarı hesaplarken lot, tarih ve birim ayrımlarını koruyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Kalabalık saha","Yaya ve ekipman trafiği arttığında: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Hafta başı","Haftanın ilk sevkiyatında: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Parti ayrımı · Alan doluluğu","Bekleme alanı dolmaya başladığında: aynı ürünün farklı lotları ayrı izlenebilirlik gerektirebilir.","Lotları tek kayıt altında kontrolsüz birleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Dar koridor","Çalışma alanı daraldığında: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Vardiya devri","İş başka personele devredilirken: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Çift okutma · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: aynı ürünün yanlışlıkla iki kez okutulması miktarı artırabilir.","İşlem tamamlanmadan ekrandaki miktarı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Akşam vardiyası","Günün son kabul işleminde: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yükleme rampası · Erken teslimat","Araç randevudan erken geldiğinde: rampa kenarları ve araç boşlukları düşme riski oluşturabilir.","Araç sabitleme ve rampa güvenliği prosedürlerini uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Bekleme süresi · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: araç veya palet beklemeleri operasyon verimliliğini etkiler.","Bekleme nedenini kaydetmek iyileştirmeye yardımcı olur. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Sabah ilk kabul","Vardiyanın ilk teslimatında: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Hasarlı koli · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: ezilmiş, ıslanmış veya açılmış kolilerde iç ürünün durumu ayrıca kontrol edilmelidir.","Hasar tespitini fotoğraf ve teslimat kaydıyla belgelendirmek izlenebilirliği artırır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Eksik belge","Teslimat evrakı eksik olduğunda: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Lot takibi · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: lot numarası aynı üretim partisindeki ürünleri izlemek için kullanılır.","Geri çağırma veya kalite incelemesinde lot bilgisi önemli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kaygan zemin · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: dökülen sıvılar ve ambalaj artıkları kayma ve düşme riski oluşturur.","Alanı güvenli hâle getirip sorumlu kişiye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Yer adresi · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: depo lokasyon kodları ürünün doğru rafta bulunmasını kolaylaştırır.","Yanlış adrese yerleştirme sonraki toplama işlemlerini geciktirir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Kısmi teslimat · Okuyucu arızası","Barkod okuyucu kullanılamadığında: siparişin yalnızca bir bölümü geldiyse tamamı teslim alınmış gibi kaydedilmemelidir.","Eksik kalan miktarı açık şekilde takip edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · İade dönüşü","Geri gelen ürünler ayrıştırılırken: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım kilidi · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: sayım sürerken kontrolsüz stok hareketleri sayım farkı oluşturabilir.","Sayım alanının işlem kurallarını uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · Manuel giriş","Barkod yerine elle kod yazılırken: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Ürün uyumluluğu · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: birbiriyle uyumsuz ürünlerin yan yana depolanması kalite ve güvenlik riski yaratabilir.","Ürünlerin özel saklama talimatlarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yük altında durma · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: askıda veya kaldırılmış yükün altında bulunmak ciddi tehlike oluşturur.","Yükün altından geçmeyin ve çalışma alanını güvenli tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Eksik yükleme · Eğitim uygulaması","Personel iş başında eğitim alırken: hazırlanan ürünün araca eksik alınması teslimat farkı oluşturabilir.","Yükleme sonu kontrol listesi kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Çevrimdışı kayıt · Gün sonu raporu","Günün işlemleri raporlanırken: çevrimdışı çalışan sistemlerde veri eşitleme kuralları önemlidir.","Bağlantı geri geldiğinde mükerrer kayıt olup olmadığını kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Cross-docking · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: cross-docking, gelen ürünün uzun süre stokta tutulmadan çıkış sevkiyatına yönlendirilmesidir.","Doğru ürün ayrıştırması ve zamanlama bu modelde özellikle önemlidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Sayım günü","Depoda planlı sayım yapılırken: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Acil çıkışlar · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: acil çıkış yolları palet, koli veya ekipmanla kapatılmamalıdır.","Kaçış güzergâhlarını sürekli erişilebilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Bayram öncesi","Sevkiyat hacmi artmışken: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Negatif stok · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: negatif stok, süreç veya kayıt zamanlaması sorununa işaret edebilir.","Hareket kayıtlarını incelemeden rastgele giriş yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Palet değişimi","Yük başka bir palete aktarılırken: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Kampanya dönemi","Ürün hareketi normalden hızlıyken: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet yük etiketi · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: palet üzerindeki ürün ve miktar etiketi fiziksel yükle tutarlı olmalıdır.","Yanlış etiketi düzeltmeden paleti sevke bırakmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Etiket tutarsızlığı · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: ürün etiketiyle irsaliye bilgisi uyuşmadığında yanlış kabul riski doğar.","Ürün kimliğini doğrulamadan kabulü kesinleştirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Kalabalık saha","Yaya ve ekipman trafiği arttığında: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Hafta başı","Haftanın ilk sevkiyatında: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç kapasitesi · Alan doluluğu","Bekleme alanı dolmaya başladığında: araçların azami yüklü ağırlığı ve hacim sınırları aşılmamalıdır.","Yük planını araç ve mevzuat sınırlarına göre doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Dar koridor","Çalışma alanı daraldığında: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Vardiya devri","İş başka personele devredilirken: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Yetki ayrımı · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: kullanıcı rollerinin yetkileri göreve göre sınırlandırılmalıdır.","Yetkisiz hesapla kayıt düzeltme yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Akşam vardiyası","Günün son kabul işleminde: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Raf kapasitesi · Erken teslimat","Araç randevudan erken geldiğinde: raf sistemlerinde yükler izin verilen taşıma kapasitesini aşmamalıdır.","Yükün yalnızca ağırlığını değil, yerleşimini ve raf gözünün sınırlarını da dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Sayım farkı · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: sayım farkları yalnızca yanlış sayımdan değil, eksik hareket kaydından da kaynaklanabilir.","Düzeltmeden önce işlem geçmişi ve ürün birimlerini inceleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Sabah ilk kabul","Vardiyanın ilk teslimatında: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye fotoğrafı · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: belge görüntüsü okunaklı değilse otomatik okuma sonucu doğrulanmalıdır.","Ürün kodu ve miktarı görüntüyle karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Eksik belge","Teslimat evrakı eksik olduğunda: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Yeniden sipariş noktası · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: stok belirli seviyeye düştüğünde ikmal planı başlatılabilir.","Talep hızı ve tedarik süresini birlikte değerlendirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet tipi · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: farklı palet ölçüleri raf ve ekipman uyumluluğunu etkiler.","Paleti kullanılacağı ekipmana uygun seçin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Kontrol basamağı · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: bazı barkod türlerinde hatalı girişleri yakalamak için kontrol basamağı bulunur.","Kod uzunluğunu ve doğrulama sonucunu kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Sızıntı · Okuyucu arızası","Barkod okuyucu kullanılamadığında: sızdıran ürünler çevredeki kolilere ve zemine zarar verebilir.","Alanı güvenli hâle getirip uygun müdahale prosedürünü izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · İade dönüşü","Geri gelen ürünler ayrıştırılırken: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yangın ekipmanı · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: yangın söndürücü ve alarm noktalarının önü kapatılmamalıdır.","Erişim alanlarını açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · Manuel giriş","Barkod yerine elle kod yazılırken: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Sevkiyat önceliği · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: acil sevkiyatlar planı değiştirebilir ancak kontrol adımları atlanmamalıdır.","Öncelik değişikliğini ekiplerle paylaşın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Eksik teslimat · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: i̇rsaliyede yazan miktar ile fiziksel sayım uyuşmuyorsa eksik teslimat kaydı açılmalıdır.","Ürün kodunu, koli içi adedi ve sayım birimini tekrar doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Çift kayıt riski · Eğitim uygulaması","Personel iş başında eğitim alırken: aynı sevkiyatın iki kez kaydedilmesi stokları olduğundan yüksek gösterebilir.","Yeni kayıt açmadan önce irsaliye ve araç bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Mühür kontrolü · Gün sonu raporu","Günün işlemleri raporlanırken: araç mührü bulunan sevkiyatlarda mühür bilgisi teslimat belgeleriyle karşılaştırılmalıdır.","Uyuşmazlık varsa mührü rastgele değiştirmeyin; prosedüre göre kayıt açın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok yaşlanması · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: uzun süre hareketsiz kalan ürünler stok maliyetini artırabilir.","Yaşlanan stokları düzenli raporlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Sayım günü","Depoda planlı sayım yapılırken: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Zemin yükü · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: depo zeminleri ve platformlar belirli taşıma sınırlarına sahiptir.","Yükü zeminin izin verilen kapasitesine göre yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Bayram öncesi","Sevkiyat hacmi artmışken: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Elle taşıma · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: ağır veya hacimli yüklerin elle kaldırılması kas-iskelet yaralanmalarına yol açabilir.","Uygun yardımcı ekipman ve güvenli taşıma yöntemlerini kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Palet değişimi","Yük başka bir palete aktarılırken: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Kampanya dönemi","Ürün hareketi normalden hızlıyken: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Elleçleme · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: ürünün taşınması, ayrıştırılması ve yerleştirilmesi elleçleme faaliyetleridir.","Gereksiz elleçleme adımlarını azaltmak hasar riskini düşürebilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FIFO nedir? · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: fIFO, depoya ilk giren stokun önce çıkmasını esas alır.","Son kullanma tarihli ürünlerde işletmenin FEFO kuralı öncelikli olabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Kalabalık saha","Yaya ve ekipman trafiği arttığında: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Hafta başı","Haftanın ilk sevkiyatında: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Son kullanma tarihi · Alan doluluğu","Bekleme alanı dolmaya başladığında: tarihi geçmiş ürünlerin normal sevkiyat akışına karışmaması gerekir.","İşletmenin karantina ve kalite kontrol prosedürlerini izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Dar koridor","Çalışma alanı daraldığında: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Vardiya devri","İş başka personele devredilirken: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Standart işlem adımları · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: standart kontrol sırası, yoğun saatlerde unutulan adımları azaltmaya yardımcı olur.","Ürün kodu, miktar, hasar ve belge kontrolünü aynı düzende yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Akşam vardiyası","Günün son kabul işleminde: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Karantina stoğu · Erken teslimat","Araç randevudan erken geldiğinde: kontrol bekleyen ürünler kullanılabilir stoktan ayrı yönetilmelidir.","Kalite onayı olmadan sevkiyata yönlendirmeyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Nem kontrolü · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: yüksek nem bazı ambalaj ve ürünlerde bozulmaya yol açabilir.","Ürün koşullarına uygun nem takibi yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Sabah ilk kabul","Vardiyanın ilk teslimatında: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Forklift kör noktası · Ekip değişimi","Farklı ekipler aynı sevkiyatta çalışırken: forklift operatörü bazı alanları doğrudan göremeyebilir.","İşaretli yaya yollarını kullanın ve operatörle güvenli iletişim kurun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Eksik belge","Teslimat evrakı eksik olduğunda: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yükleme sırası · İşlem kapatma","Görev tamamlandı olarak işaretlenmeden hemen önce: yükleme sırası teslimat rotası ve yük dengesi açısından önemlidir.","Araç yükleme planına uygun hareket edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Darboğaz · Yeni çalışan","İşlemi yeni başlayan personel yürütürken: operasyonun en yavaş aşaması toplam iş akışını sınırlayabilir.","Bekleme sürelerini aşama bazında ölçün. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Hasarlı ambalaj","Ambalaj üzerinde hasar şüphesi varken: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görev devri · Sistem karşılaştırması","Fiziksel ürünle dijital kayıt karşılaştırılırken: vardiya değişiminde tamamlanmamış işler görünür şekilde aktarılmalıdır.","Açık sevkiyat, hasar ve bekleyen paletleri belirtin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Veri doğrulama · Okuyucu arızası","Barkod okuyucu kullanılamadığında: zorunlu alanlar ve uygun değer kontrolleri kayıt kalitesini artırır.","Hatalı ürün kodunu veya boş miktarı işlem tamamlanmadan düzeltin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Fazla teslimat · İade dönüşü","Geri gelen ürünler ayrıştırılırken: beklenenden fazla gelen ürünler onay alınmadan stoklara rastgele eklenmemelidir.","Fazlalığı ayrı kaydedip yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Birim dönüşümü · Müşteri şikâyeti","Önceki sevkiyatla ilgili şikâyet geldiğinde: adet, koli ve palet farklı ölçü birimleridir; dönüşüm ürünün koli içi adedine bağlıdır.","48 adetlik koliyle 24 adetlik kolinin dönüşümü aynı değildir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Okunmayan etiket · Manuel giriş","Barkod yerine elle kod yazılırken: kirli, yırtık veya kırışmış barkodlar yanlış ya da başarısız okumaya yol açabilir.","Elle girişte kodu iki kez doğrulamak hata riskini azaltır. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","ABC analizi · Kısmi sevkiyat","Sipariş parça parça teslim edilirken: aBC analizi stokları seçilen önem ölçütüne göre sınıflandırır.","Yüksek değerli veya kritik ürünlerde daha sık kontrol planlanabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Araç bilgisi · Tedarikçi uyuşmazlığı","Teslim edilen miktar konusunda anlaşmazlık çıktığında: plaka ve firma bilgilerinin doğru kaydedilmesi teslimatın geriye dönük izlenmesini kolaylaştırır.","Eksik bilgi varsa kaydı tamamlamadan önce doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Tekil tanımlama · Tekrar kontrol","İlk kontrolden sonra ikinci sayım yapılırken: barkodun tek başına ürünün tüm özelliklerini içerdiği varsayılmamalıdır.","Ürün kartındaki birim, varyant ve kod bilgilerini kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Teslim saatinin kaydı · Benzer ambalaj","Birbirine benzeyen ürünler yan yanayken: fiilî teslim alma saatinin doğru tutulması operasyon analizlerini destekler.","Araç varışı ile boşaltma başlangıcını birbirine karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Seri numarası · Yer değişikliği","Depo lokasyonları yeniden düzenlenirken: seri numaralı ürünlerde yalnızca ürün adedi yeterli kayıt olmayabilir.","İşletme kuralına göre her seri numarasını ayrı doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Rezerv stok · Tek koli farkı","Sayımda yalnızca bir koli fark bulunduğunda: siparişe ayrılmış stok fiziksel olarak depoda bulunsa da serbestçe kullanılabilir olmayabilir.","Kullanılabilir stok ile toplam stoğu ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Güvenlik stoğu · Yeni ürün","Kataloğa yeni eklenmiş ürün teslim alınırken: güvenlik stoğu beklenmeyen talep veya tedarik gecikmesine karşı tampon görevi görür.","Miktarı talep ve tedarik koşullarına göre belirlenmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet taşması · Eğitim uygulaması","Personel iş başında eğitim alırken: koli palet kenarından taşarsa çarpma ve hasar riski artabilir.","Yük ölçülerini taşıma ve raf koşullarına göre kontrol edin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Koridor açıklığı · Toplu kontrol","Çok sayıda koli birlikte kontrol edilirken: depo koridorlarındaki engeller ekipman hareketini ve acil erişimi zorlaştırır.","Geçiş alanlarını işletme planına uygun açık tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","GS1 kodları · Yeni tedarikçi","İlk kez çalışılan tedarikçiden mal gelirken: bazı GS1 barkodları ürün yanında lot veya tarih gibi ek veriler içerebilir.","Okuyucu çıktısını kullanılan barkod standardına göre yorumlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Ürün varyantı · Gün sonu raporu","Günün işlemleri raporlanırken: benzer ambalajlı ürünlerin boyut veya içerik varyantları farklı kodlara sahip olabilir.","Varyant bilgisini ürün kartıyla eşleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","İzlenebilirlik · Hızlı sevk","Ürün kabulden kısa süre sonra sevk edilecekken: ürünün kaynağı ve hareketlerinin izlenebilmesi kalite olaylarında önemlidir.","Tedarikçi, lot, tarih ve sevkiyat kayıtlarını doğru tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Hasarlı elektrik kablosu · Sistem yavaşlığı","Uygulama yanıtı gecikmişken: ezilmiş veya açıkta iletkeni olan kablolar elektrik tehlikesi oluşturur.","Ekipmanı kullanmayın; yetkili teknik ekibe bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Yorgunluk · Denetim hazırlığı","İşlem kayıtları denetime hazırlanırken: yorgunluk dikkat ve tepki süresini olumsuz etkileyebilir.","Güvensiz çalışma koşullarını amire bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Yanlış mağaza · Geçici bekletme","Ürün kısa süreli bekleme alanına alındığında: yanlış sevkiyat adresi ürünün gecikmesine ve ek taşıma maliyetine yol açabilir.","Sevk emri ile hedef adresi karşılaştırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Geri lojistik · Sayım günü","Depoda planlı sayım yapılırken: i̇ade ve geri kazanım akışları normal sevkiyattan farklı kayıtlar gerektirebilir.","İade nedenini ve malzeme durumunu izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Görsel yönetim · İptal edilen işlem","Bir kabul veya sevkiyat iptal edildiğinde: açık etiket ve alan işaretleri yanlış işlem riskini azaltabilir.","İşaretleri tutarlı ve okunabilir tutun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Zaman damgası · Raf yerleşimi","Ürün yüksek rafa yerleştirilecekken: i̇şlem zamanının kaydı süreçlerin geriye dönük incelenmesini sağlar.","Cihaz saati ve sunucu saatinin farklarını dikkate alın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","FEFO nedir? · Bayram öncesi","Sevkiyat hacmi artmışken: fEFO, son kullanma tarihi daha yakın uygun ürünün önce sevk edilmesini esas alır.","Ürün uygunluğu ve işletmenin sevkiyat kuralları ayrıca kontrol edilmelidir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Palet sağlamlığı · Düzeltme talebi","Önceki işlemde hata bildirildiğinde: kırık tahta, çıkmış çivi veya dengesiz yük taşıyan paletler risk oluşturur.","Hasarlı paletleri işletme prosedürüne göre ayırın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Stok doğruluğu · Palet değişimi","Yük başka bir palete aktarılırken: sistem stoğuyla fiziksel stok arasındaki uyum, güvenilir sevkiyat planlamasının temelidir.","Yanlış ürün kodu ve eksik hareket kaydı stok farkı oluşturabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","İstif dengesi · Kampanya dönemi","Ürün hareketi normalden hızlıyken: ağır kolilerin dengesiz şekilde üste konması yük kayması riskini artırabilir.","Ürün ve ambalaj talimatlarına uygun istif yapın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Ürün kodu kontrolü · Şüpheli miktar","Girilen miktar beklenenden farklı göründüğünde: benzer ürün adları farklı stok kodlarına sahip olabilir.","Sadece ürün adına bakarak sayım girişi yapmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İrsaliye numarası · Rampa değişimi","Araç farklı bir rampaya yönlendirildiğinde: i̇rsaliye numarası teslimatı diğer sevkiyatlardan ayırmaya yardımcı olur.","Aynı firmadan gelen farklı araçların belgelerini karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Sipariş karşılaştırması · Hafta sonu öncesi","Hafta sonu öncesindeki son işlemde: teslimatın siparişle uyumu ürün kodu ve miktar bazında kontrol edilmelidir.","Sipariş dışı ürünleri ayrı işaretleyip yetkili onayı isteyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","İade gelen ürün · Etiket hasarı","Ürün etiketi okunamaz hâle geldiğinde: müşteri iadesi ile tedarikçi teslimatı farklı kabul süreçleri gerektirebilir.","İade ürünün durumunu ve iade nedenini ayrıca kaydedin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Mal Kabul","Tartım kontrolü · Kalabalık saha","Yaya ve ekipman trafiği arttığında: ağırlıkla teslim alınan ürünlerde ölçüm birimi ve tartı doğruluğu önemlidir.","Net ve brüt ağırlık kavramlarını karıştırmayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Transfer kaydı · Hafta başı","Haftanın ilk sevkiyatında: depo içi yer değişiklikleri kayıt altına alınmazsa ürün bulunamayabilir.","Çıkış ve varış lokasyonlarını doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Stok","Çevrim sayımı · Alan doluluğu","Bekleme alanı dolmaya başladığında: çevrim sayımı tüm depoyu durdurmadan seçili stokların periyodik kontrolüdür.","Sayım sıklığını risk ve ürün hareketine göre belirleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Palet","Boş palet istifi · Dar koridor","Çalışma alanı daraldığında: boş paletlerin dengesiz istiflenmesi devrilme riski yaratır.","İstif yüksekliği ve alan kurallarına uyun. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Depolama","Sıcaklık kaydı · Vardiya devri","İş başka personele devredilirken: sıcaklık hassasiyeti olan ürünlerde ortam takibi izlenebilirlik sağlar.","Limit dışı ölçümleri prosedüre göre bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Barkod","Etiket konumu · Yanlış yönlendirme","Ürün yanlış alana bırakıldığında: kavisli veya kırışık yüzeye yerleştirilen barkod zor okunabilir.","Etiketi uygun düz bir yüzeye yerleştirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Kalite","Koku değişimi · Yakın tarihli ürün","Son kullanma tarihi yaklaşan ürün geldiğinde: beklenmeyen koku bazı ürünlerde kalite sorununa işaret edebilir.","Ürünü kullanıma açmadan yetkiliye bildirin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Kişisel koruyucu donanım · Akşam vardiyası","Günün son kabul işleminde: gerekli koruyucu donanım işin risk değerlendirmesine göre belirlenir.","Saha kurallarında belirtilen ekipmanı doğru kullanın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["İş Güvenliği","Geri manevra · Erken teslimat","Araç randevudan erken geldiğinde: araçların geri manevrası yaya ve ekipman çarpışma riskini artırır.","Belirlenmiş manevra alanı ve yönlendirme kurallarını izleyin. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Sevkiyat","Teslimat kanıtı · Çoklu lot","Aynı üründen birden fazla lot geldiğinde: teslimatın kayıtla doğrulanması sonradan oluşan uyuşmazlıkları azaltır.","Yetkili teslim alma ve belge prosedürünü uygulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Lojistik","Rampa planlama · Yoğun rampa saati","Birden fazla araç aynı anda beklerken: araçların aynı anda rampaya yönelmesi kuyruk oluşturabilir.","Rampa kapasitesi ve araç randevularını birlikte planlayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Verimlilik","Tekrar işleme · Araç gecikmesi","Teslimat planlanan saatten geç geldiğinde: yanlış ürün veya miktar kaydı aynı işi yeniden yapmayı gerektirebilir.","İlk seferde doğrulama toplam iş yükünü azaltabilir. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."],["Teknoloji","Mobil veri bağlantısı · Farklı birim","Adet ve koli birimleri birlikte kullanılırken: zayıf bağlantı işlemlerin sunucuya geç ulaşmasına neden olabilir.","Kaydın başarıyla tamamlandığını ekranda doğrulayın. Bu senaryoda işlem bitmeden önce kontrolün gerçekten yapıldığını doğrulayın."]];
const KEY='aktiva_count_tip_login_index_v1';
let currentIndex=null, active=false, expanded=false, expandedIndex=null;
function enter(){
 if(active)return;
 active=true;
 try{const prev=Number(localStorage.getItem(KEY));currentIndex=(Number.isFinite(prev)?prev:-1)+1;localStorage.setItem(KEY,String(currentIndex));}
 catch{currentIndex=(currentIndex??-1)+1;}
 expanded=false;expandedIndex=currentIndex;
}
const tip=()=>tips[((currentIndex%tips.length)+tips.length)%tips.length];
document.addEventListener('aktiva:session-changed',()=>{
 if(document.body.dataset.role==='count'){enter();paint();}
 else{active=false;expanded=false;}
});
function paint(){const root=document.querySelector('#akd-dashboard .akd-body');if(!root||document.body.dataset.role!=='count')return;const greeting=root.querySelector('.akd-greeting'),actions=root.querySelector('.akd-actions');if(!greeting||!actions)return;if(!active)enter();const key=String(currentIndex);if(expandedIndex!==currentIndex){expanded=false;expandedIndex=currentIndex;}let card=root.querySelector('#akd-daily-tip');if(card&&card.dataset.day===key)return;const [category,title,short,detail]=tip();if(!card){card=document.createElement('section');card.id='akd-daily-tip';card.className='akd-daily-tip';greeting.insertAdjacentElement('afterend',card)}card.dataset.day=key;card.innerHTML='<div class="akd-daily-head"><span>✦ Günün Depo Bilgisi</span><span class="akd-daily-category"></span></div><h2 class="akd-daily-title"></h2><p class="akd-daily-short"></p><p class="akd-daily-detail" hidden></p><button type="button" class="akd-daily-toggle" aria-expanded="false">Detayını Oku ›</button>';card.querySelector('.akd-daily-category').textContent=category;card.querySelector('.akd-daily-title').textContent=title;card.querySelector('.akd-daily-short').textContent=short;card.querySelector('.akd-daily-detail').textContent=detail;const d=card.querySelector('.akd-daily-detail'),b=card.querySelector('button');const sync=()=>{d.hidden=!expanded;b.textContent=expanded?'Detayı Kapat ↑':'Detayını Oku ›';b.setAttribute('aria-expanded',String(expanded))};sync();b.onclick=()=>{expanded=!expanded;sync()};}
function init(){if(!document.getElementById('akd-dashboard'))return;const observer=new MutationObserver(()=>{if(!document.hidden)paint()});observer.observe(document.getElementById('akd-dashboard'),{childList:true,subtree:true});paint();setInterval(paint,60000)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
